//go:build linux

// Package wireguardstate owns the narrow on-disk provenance contract for the
// WireGuard artifacts generated by SysWarden. It deliberately has no dependency
// on the network, firewall, system, or command packages so removal and package
// lifecycle code can consume the same attestation primitives.
package wireguardstate

import (
	"bytes"
	cryptorand "crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"net/netip"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"syscall"
	"unicode/utf8"

	"golang.org/x/sys/unix"
)

const (
	ManifestPath                 = "/etc/wireguard/.syswarden-ownership-v1.json"
	TransactionPath              = "/etc/wireguard/.syswarden-transaction-v1.json"
	ServerConfigurationPath      = "/etc/wireguard/wg-syswarden.conf"
	ClientConfigurationPath      = "/etc/wireguard/clients/admin-pc.conf"
	ForwardingConfigurationPath  = "/etc/sysctl.d/99-syswarden-wireguard.conf"
	OpenRCServiceLinkPath        = "/etc/init.d/wg-quick.wg-syswarden"
	OpenRCServiceLinkTarget      = "/etc/init.d/wg-quick"
	manifestSchema               = "syswarden-wireguard-ownership-v1"
	transactionSchema            = "syswarden-wireguard-transaction-v1"
	transactionScratchName       = ".syswarden-transaction-v1.json.tmp"
	transactionNextName          = ".syswarden-transaction-v1.json.next"
	transactionQuarantineName    = ".syswarden-transaction-v1.json.remove"
	transactionScratchQuarantine = ".syswarden-transaction-v1.json.tmp.remove"
	transactionNextQuarantine    = ".syswarden-transaction-v1.json.next.remove"
	maximumOwnedArtifactBytes    = 1 << 20
	maximumOwnershipManifestSize = 32 << 10
)

var canonicalArtifactPaths = [...]string{
	ServerConfigurationPath,
	ClientConfigurationPath,
	ForwardingConfigurationPath,
}

var wireGuardInterfacePattern = regexp.MustCompile(`^[A-Za-z0-9_.:-]{1,15}$`)
var wireGuardOwnershipTokenPattern = regexp.MustCompile(`^[0-9a-f]{64}$`)

var trustedNFTExecutablePaths = [...]string{
	"/usr/bin/nft",
	"/usr/sbin/nft",
	"/bin/nft",
	"/sbin/nft",
}

var trustedTrueExecutablePaths = [...]string{
	"/usr/bin/true",
	"/bin/true",
}

// ServerConfigurationIdentity is the non-secret runtime ownership identity
// extracted from an exact generated WireGuard server configuration.
type ServerConfigurationIdentity struct {
	NFTPath         string
	TruePath        string
	OwnershipToken  string
	ActiveInterface string
}

// Artifact records the exact file identity accepted as SysWarden-owned.
// Mode is the permission bit value, for example 384 for 0600.
type Artifact struct {
	Path   string `json:"path"`
	SHA256 string `json:"sha256"`
	Mode   uint32 `json:"mode"`
	UID    uint32 `json:"uid"`
	GID    uint32 `json:"gid"`
	NLink  uint64 `json:"nlink"`
	Device uint64 `json:"device"`
	Inode  uint64 `json:"inode"`
}

// Manifest is the canonical ownership envelope for the exact generated set.
type Manifest struct {
	Schema            string           `json:"schema"`
	Artifacts         []Artifact       `json:"artifacts"`
	OpenRCServiceLink *SymlinkArtifact `json:"openrc_service_link,omitempty"`
}

// SymlinkArtifact binds a non-secret service link created by SysWarden. A nil
// manifest field means an exact preexisting operator link was never adopted.
type SymlinkArtifact struct {
	Path   string `json:"path"`
	Target string `json:"target"`
	UID    uint32 `json:"uid"`
	GID    uint32 `json:"gid"`
	NLink  uint64 `json:"nlink"`
	Device uint64 `json:"device"`
	Inode  uint64 `json:"inode"`
}

// Inventory is a no-follow presence inventory for the complete bounded state.
type Inventory struct {
	Manifest bool
	// Transaction is true when the final journal or either fixed journal
	// publication scratch path exists. Unsafe file types still count as present.
	Transaction bool
	Artifacts   []string
}

// TransactionOperation identifies the only bounded durable operations accepted
// by the WireGuard state journal.
type TransactionOperation string

const (
	TransactionOperationNone                TransactionOperation = ""
	TransactionOperationPublish             TransactionOperation = "publish"
	TransactionOperationRemove              TransactionOperation = "remove"
	TransactionOperationRemovePendingReload TransactionOperation = "remove-reload"
)

// Empty reports whether no managed final path or durable journal is present.
func (inventory Inventory) Empty() bool {
	return !inventory.Manifest && !inventory.Transaction && len(inventory.Artifacts) == 0
}

type journalArtifact struct {
	Artifact       Artifact `json:"artifact"`
	StageName      string   `json:"stage_name,omitempty"`
	QuarantineName string   `json:"quarantine_name"`
}

type transactionJournal struct {
	Schema            string            `json:"schema"`
	Operation         string            `json:"operation"`
	Artifacts         []journalArtifact `json:"artifacts"`
	Manifest          *journalArtifact  `json:"manifest,omitempty"`
	OpenRCServiceLink *journalSymlink   `json:"openrc_service_link,omitempty"`
}

type journalSymlink struct {
	Artifact       SymlinkArtifact `json:"artifact"`
	StageName      string          `json:"stage_name,omitempty"`
	QuarantineName string          `json:"quarantine_name"`
}

type pinnedDirectory struct {
	file *os.File
}

type stagedEntry struct {
	directory      *pinnedDirectory
	logical        string
	finalName      string
	stageName      string
	quarantineName string
	record         Artifact
	published      bool
}

var wireGuardStateFaultPoint = func(string) {}

// StagedPublication holds privately staged files until the caller has
// completed any external reattestation required immediately before publish.
type StagedPublication struct {
	root          string
	expectedUID   uint32
	expectedGID   uint32
	entries       []*stagedEntry
	journal       transactionJournal
	journalRecord Artifact
	committed     bool
	closed        bool
}

// StagedManifest is a manifest staged inside an existing durable publication.
type StagedManifest struct {
	publication *StagedPublication
	entry       *stagedEntry
}

// ArtifactPaths returns a copy of the fixed generated-artifact inventory.
func ArtifactPaths() []string {
	paths := make([]string, len(canonicalArtifactPaths))
	copy(paths, canonicalArtifactPaths[:])
	return paths
}

func attestRootExecutable(path string) error {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return fmt.Errorf("WireGuard hook executable path is not canonical and absolute")
	}
	resolved, err := filepath.EvalSymlinks(path)
	if err != nil {
		return fmt.Errorf("resolve WireGuard hook executable %s: %w", path, err)
	}
	if resolved != path {
		return fmt.Errorf("WireGuard hook executable %s is not an exact resolved path", path)
	}
	for current := filepath.Dir(path); ; current = filepath.Dir(current) {
		info, err := os.Lstat(current)
		if err != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || info.Mode().Perm()&0022 != 0 {
			return fmt.Errorf("WireGuard hook executable parent %s is not protected", current)
		}
		stat, ok := info.Sys().(*syscall.Stat_t)
		if !ok || stat.Uid != 0 {
			return fmt.Errorf("WireGuard hook executable parent %s is not root-owned", current)
		}
		if current == "/" {
			break
		}
	}
	info, err := os.Lstat(path)
	if err != nil {
		return fmt.Errorf("inspect WireGuard hook executable %s: %w", path, err)
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || info.Mode().Perm()&0111 == 0 ||
		info.Mode().Perm()&0022 != 0 || stat.Uid != 0 || stat.Nlink == 0 {
		return fmt.Errorf("WireGuard hook executable %s is not an exact protected root-owned file", path)
	}
	return nil
}

// AttestServerHookExecutables verifies the exact protected executable paths
// embedded in a previously parsed SysWarden WireGuard server configuration.
// Callers must invoke it immediately before wg-quick start or stop.
func AttestServerHookExecutables(identity ServerConfigurationIdentity) error {
	trustedNFT := false
	for _, path := range trustedNFTExecutablePaths {
		trustedNFT = trustedNFT || identity.NFTPath == path
	}
	trustedTrue := false
	for _, path := range trustedTrueExecutablePaths {
		trustedTrue = trustedTrue || identity.TruePath == path
	}
	if !trustedNFT || !trustedTrue {
		return fmt.Errorf("WireGuard hook identity contains an unsupported executable path")
	}
	if err := attestRootExecutable(identity.NFTPath); err != nil {
		return fmt.Errorf("attest WireGuard nft hook executable: %w", err)
	}
	if err := attestRootExecutable(identity.TruePath); err != nil {
		return fmt.Errorf("attest WireGuard no-op hook executable: %w", err)
	}
	return nil
}

func exactConfigurationValue(line, prefix string) (string, error) {
	if !strings.HasPrefix(line, prefix) {
		return "", fmt.Errorf("WireGuard configuration line must start with %q", prefix)
	}
	value := strings.TrimPrefix(line, prefix)
	if value == "" || strings.TrimSpace(value) != value {
		return "", fmt.Errorf("WireGuard configuration value for %q is not canonical", prefix)
	}
	return value, nil
}

func verifyCanonicalWireGuardKey(value string) error {
	decoded, err := base64.StdEncoding.DecodeString(value)
	if err != nil || len(decoded) != 32 || base64.StdEncoding.EncodeToString(decoded) != value {
		return fmt.Errorf("WireGuard configuration contains a noncanonical key")
	}
	return nil
}

func trustedNFTPathFromPostUp(postUp string) (string, error) {
	for _, path := range trustedNFTExecutablePaths {
		if strings.HasPrefix(postUp, path+" ") {
			return path, nil
		}
	}
	return "", fmt.Errorf("WireGuard PostUp does not use a fixed trusted nft path")
}

// ParseServerConfiguration accepts only the exact SysWarden-generated server
// shape and returns its non-secret runtime ownership identity.
func ParseServerConfiguration(content []byte) (ServerConfigurationIdentity, error) {
	if len(content) == 0 || len(content) > maximumOwnedArtifactBytes || !utf8.Valid(content) {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard server configuration has invalid size or encoding")
	}
	for _, value := range content {
		if value > 0x7f || value == 0 {
			return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard server configuration must be ASCII text")
		}
	}
	lines := strings.Split(string(content), "\n")
	if len(lines) != 12 || lines[0] != "[Interface]" || lines[6] != "" ||
		lines[7] != "[Peer]" || lines[11] != "" {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard server configuration has a noncanonical structure")
	}

	address, err := exactConfigurationValue(lines[1], "Address = ")
	if err != nil {
		return ServerConfigurationIdentity{}, err
	}
	serverPrefix, err := netip.ParsePrefix(address)
	if err != nil || !serverPrefix.Addr().Is4() || serverPrefix.Addr().Is4In6() ||
		serverPrefix.Bits() > 30 || serverPrefix.String() != address {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard server Address is not canonical IPv4")
	}
	networkPrefix := serverPrefix.Masked()
	if serverPrefix.Addr() != networkPrefix.Addr().Next() {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard server Address is not the first subnet host")
	}

	portValue, err := exactConfigurationValue(lines[2], "ListenPort = ")
	if err != nil {
		return ServerConfigurationIdentity{}, err
	}
	port, err := strconv.Atoi(portValue)
	if err != nil || port < 1 || port > 65535 || strconv.Itoa(port) != portValue {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard ListenPort is not canonical")
	}
	privateKey, err := exactConfigurationValue(lines[3], "PrivateKey = ")
	if err != nil || verifyCanonicalWireGuardKey(privateKey) != nil {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard server PrivateKey is not canonical")
	}

	postUp, err := exactConfigurationValue(lines[4], "PostUp = ")
	if err != nil {
		return ServerConfigurationIdentity{}, err
	}
	nftPath, err := trustedNFTPathFromPostUp(postUp)
	if err != nil {
		return ServerConfigurationIdentity{}, err
	}
	tokenMarker := `comment "syswarden-wg-v1:`
	tokenStart := strings.Index(postUp, tokenMarker)
	if tokenStart < 0 {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard PostUp has no ownership token")
	}
	tokenStart += len(tokenMarker)
	tokenEnd := strings.Index(postUp[tokenStart:], `"; }`)
	if tokenEnd < 0 {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard PostUp has no canonical ownership token")
	}
	ownershipToken := postUp[tokenStart : tokenStart+tokenEnd]
	if !wireGuardOwnershipTokenPattern.MatchString(ownershipToken) {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard PostUp ownership token is invalid")
	}
	interfaceMarker := `add rule inet syswarden_wg postrouting oifname "`
	interfaceStart := strings.Index(postUp, interfaceMarker)
	if interfaceStart < 0 {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard PostUp has no exact masquerade rule")
	}
	interfaceStart += len(interfaceMarker)
	interfaceEnd := strings.Index(postUp[interfaceStart:], `" masquerade;`)
	if interfaceEnd < 0 {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard PostUp has no canonical masquerade interface")
	}
	activeInterface := postUp[interfaceStart : interfaceStart+interfaceEnd]
	if !wireGuardInterfacePattern.MatchString(activeInterface) {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard PostUp has an invalid masquerade interface")
	}
	expectedPostUp := fmt.Sprintf(`%s 'create table inet syswarden_wg { comment "syswarden-wg-v1:%s"; }; add chain inet syswarden_wg prerouting { type nat hook prerouting priority dstnat; }; add chain inet syswarden_wg postrouting { type nat hook postrouting priority srcnat; }; add chain inet syswarden_wg forward { type filter hook forward priority 0; policy accept; }; add rule inet syswarden_wg postrouting oifname "%s" masquerade; add rule inet syswarden_wg forward iifname "wg-syswarden" accept; add rule inet syswarden_wg forward oifname "wg-syswarden" accept'`, nftPath, ownershipToken, activeInterface)
	if postUp != expectedPostUp {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard PostUp is not the exact owned nftables hook")
	}
	postDown, err := exactConfigurationValue(lines[5], "PostDown = ")
	if err != nil {
		return ServerConfigurationIdentity{}, err
	}
	truePath := ""
	for _, candidate := range trustedTrueExecutablePaths {
		if postDown == candidate {
			truePath = candidate
			break
		}
	}
	if truePath == "" {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard PostDown must be a fixed no-op executable")
	}

	publicKey, err := exactConfigurationValue(lines[8], "PublicKey = ")
	if err != nil || verifyCanonicalWireGuardKey(publicKey) != nil {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard peer PublicKey is not canonical")
	}
	presharedKey, err := exactConfigurationValue(lines[9], "PresharedKey = ")
	if err != nil || verifyCanonicalWireGuardKey(presharedKey) != nil {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard peer PresharedKey is not canonical")
	}
	allowed, err := exactConfigurationValue(lines[10], "AllowedIPs = ")
	if err != nil {
		return ServerConfigurationIdentity{}, err
	}
	clientPrefix, err := netip.ParsePrefix(allowed)
	if err != nil || clientPrefix.Bits() != 32 || !clientPrefix.Addr().Is4() ||
		clientPrefix.Addr().Is4In6() || clientPrefix.String() != allowed ||
		clientPrefix.Addr() != serverPrefix.Addr().Next() || !networkPrefix.Contains(clientPrefix.Addr()) {
		return ServerConfigurationIdentity{}, fmt.Errorf("WireGuard peer AllowedIPs is not the canonical second subnet host")
	}
	return ServerConfigurationIdentity{
		NFTPath: nftPath, TruePath: truePath, OwnershipToken: ownershipToken, ActiveInterface: activeInterface,
	}, nil
}

// VerifyServerConfiguration accepts only the exact SysWarden-generated server
// shape. It is intended immediately before wg-quick activation or deactivation.
func VerifyServerConfiguration(content []byte) error {
	_, err := ParseServerConfiguration(content)
	return err
}

func validateRoot(root string) error {
	if root == "" || !filepath.IsAbs(root) || filepath.Clean(root) != root {
		return fmt.Errorf("filesystem root must be canonical and absolute")
	}
	return nil
}

func hostPath(root, logical string) (string, error) {
	if err := validateRoot(root); err != nil {
		return "", err
	}
	if logical == "" || !filepath.IsAbs(logical) || filepath.Clean(logical) != logical || logical == "/" {
		return "", fmt.Errorf("owned artifact path must be canonical and absolute")
	}
	if root == "/" {
		return logical, nil
	}
	return filepath.Join(root, strings.TrimPrefix(logical, "/")), nil
}

func statIdentity(info os.FileInfo) (*syscall.Stat_t, error) {
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok {
		return nil, fmt.Errorf("file identity is unavailable")
	}
	return stat, nil
}

func sameStableIdentity(left, right os.FileInfo) bool {
	if left == nil || right == nil || !os.SameFile(left, right) || left.Mode() != right.Mode() ||
		left.Size() != right.Size() || !left.ModTime().Equal(right.ModTime()) {
		return false
	}
	leftStat, leftOK := left.Sys().(*syscall.Stat_t)
	rightStat, rightOK := right.Sys().(*syscall.Stat_t)
	return leftOK && rightOK && leftStat.Uid == rightStat.Uid && leftStat.Gid == rightStat.Gid &&
		leftStat.Nlink == rightStat.Nlink && leftStat.Dev == rightStat.Dev && leftStat.Ino == rightStat.Ino
}

func openPinnedDirectory(root, logical string, expectedUID, expectedGID uint32) (*pinnedDirectory, error) {
	if _, err := hostPath(root, logical); err != nil {
		return nil, err
	}
	fd, err := unix.Open(root, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return nil, fmt.Errorf("pin filesystem root for %s: %w", logical, err)
	}
	file := os.NewFile(uintptr(fd), root)
	if file == nil {
		_ = unix.Close(fd)
		return nil, fmt.Errorf("pin filesystem root for %s", logical)
	}
	validateDirectory := func(candidate *os.File, label string) error {
		info, err := candidate.Stat()
		if err != nil {
			return err
		}
		stat, statErr := statIdentity(info)
		if statErr != nil || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 ||
			info.Mode().Perm()&0022 != 0 || stat.Uid != expectedUID || stat.Gid != expectedGID {
			return fmt.Errorf("directory %s is not root-bound and attestable", label)
		}
		return nil
	}
	if err := validateDirectory(file, root); err != nil {
		_ = file.Close()
		return nil, err
	}
	current := file
	currentLabel := root
	for _, component := range strings.Split(strings.TrimPrefix(logical, "/"), "/") {
		nextFD, err := unix.Openat2(int(current.Fd()), component, &unix.OpenHow{
			Flags: uint64(unix.O_RDONLY | unix.O_DIRECTORY | unix.O_NOFOLLOW | unix.O_CLOEXEC),
			Resolve: uint64(unix.RESOLVE_BENEATH | unix.RESOLVE_NO_SYMLINKS |
				unix.RESOLVE_NO_MAGICLINKS | unix.RESOLVE_NO_XDEV),
		})
		if err != nil {
			_ = current.Close()
			return nil, fmt.Errorf("pin owned artifact directory component %s: %w", component, err)
		}
		nextLabel := filepath.Join(currentLabel, component)
		next := os.NewFile(uintptr(nextFD), nextLabel)
		if next == nil {
			_ = unix.Close(nextFD)
			_ = current.Close()
			return nil, fmt.Errorf("pin owned artifact directory component %s", component)
		}
		if err := validateDirectory(next, nextLabel); err != nil {
			_ = next.Close()
			_ = current.Close()
			return nil, err
		}
		_ = current.Close()
		current = next
		currentLabel = nextLabel
	}
	return &pinnedDirectory{file: current}, nil
}

func randomTemporaryName(base, purpose string) (string, error) {
	var random [16]byte
	if _, err := io.ReadFull(cryptorand.Reader, random[:]); err != nil {
		return "", fmt.Errorf("generate private staging name: %w", err)
	}
	return "." + base + ".syswarden-" + purpose + "-" + hex.EncodeToString(random[:]), nil
}

func validateOwnedFileInfo(logical string, info os.FileInfo, expectedUID, expectedGID uint32) (*syscall.Stat_t, error) {
	if info == nil || !info.Mode().IsRegular() || info.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("owned artifact %s is not a real regular file", logical)
	}
	if info.Mode().Perm() != 0600 {
		return nil, fmt.Errorf("owned artifact %s must have mode 0600", logical)
	}
	stat, err := statIdentity(info)
	if err != nil {
		return nil, fmt.Errorf("attest owned artifact %s: %w", logical, err)
	}
	if stat.Uid != expectedUID || stat.Gid != expectedGID {
		return nil, fmt.Errorf("owned artifact %s has unexpected ownership %d:%d", logical, stat.Uid, stat.Gid)
	}
	if stat.Nlink != 1 {
		return nil, fmt.Errorf("owned artifact %s must have exactly one hard link", logical)
	}
	return stat, nil
}

func recordFromFile(logical string, info os.FileInfo, digest [sha256.Size]byte, expectedUID, expectedGID uint32) (Artifact, error) {
	stat, err := validateOwnedFileInfo(logical, info, expectedUID, expectedGID)
	if err != nil {
		return Artifact{}, err
	}
	return Artifact{
		Path:   logical,
		SHA256: hex.EncodeToString(digest[:]),
		Mode:   uint32(info.Mode().Perm()),
		UID:    stat.Uid,
		GID:    stat.Gid,
		NLink:  stat.Nlink,
		Device: uint64(stat.Dev),
		Inode:  stat.Ino,
	}, nil
}

func captureAt(directory *pinnedDirectory, name, logical string, expectedUID, expectedGID uint32, limit int64) (Artifact, []byte, error) {
	fd, err := unix.Openat(int(directory.file.Fd()), name, unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return Artifact{}, nil, err
	}
	file := os.NewFile(uintptr(fd), logical)
	if file == nil {
		_ = unix.Close(fd)
		return Artifact{}, nil, fmt.Errorf("open owned artifact %s", logical)
	}
	before, err := file.Stat()
	if err != nil {
		_ = file.Close()
		return Artifact{}, nil, err
	}
	if _, err := validateOwnedFileInfo(logical, before, expectedUID, expectedGID); err != nil {
		_ = file.Close()
		return Artifact{}, nil, err
	}
	content, readErr := io.ReadAll(io.LimitReader(file, limit+1))
	after, statErr := file.Stat()
	closeErr := file.Close()
	if readErr != nil {
		return Artifact{}, nil, readErr
	}
	if statErr != nil {
		return Artifact{}, nil, statErr
	}
	if closeErr != nil {
		return Artifact{}, nil, closeErr
	}
	if int64(len(content)) > limit {
		return Artifact{}, nil, fmt.Errorf("owned artifact %s exceeds %d bytes", logical, limit)
	}
	var pathStat unix.Stat_t
	if err := unix.Fstatat(int(directory.file.Fd()), name, &pathStat, unix.AT_SYMLINK_NOFOLLOW); err != nil {
		return Artifact{}, nil, fmt.Errorf("reinspect owned artifact %s: %w", logical, err)
	}
	if !sameStableIdentity(before, after) {
		return Artifact{}, nil, fmt.Errorf("owned artifact %s changed while reading", logical)
	}
	afterStat, err := statIdentity(after)
	if err != nil || uint64(pathStat.Dev) != uint64(afterStat.Dev) || pathStat.Ino != afterStat.Ino ||
		pathStat.Nlink != afterStat.Nlink || pathStat.Mode != afterStat.Mode || pathStat.Uid != afterStat.Uid ||
		pathStat.Gid != afterStat.Gid || pathStat.Size != afterStat.Size {
		return Artifact{}, nil, fmt.Errorf("owned artifact %s path identity changed while reading", logical)
	}
	digest := sha256.Sum256(content)
	record, err := recordFromFile(logical, after, digest, expectedUID, expectedGID)
	return record, content, err
}

func captureSymlinkAt(
	directory *pinnedDirectory,
	name string,
	expectedUID, expectedGID uint32,
) (SymlinkArtifact, error) {
	var before unix.Stat_t
	if err := unix.Fstatat(int(directory.file.Fd()), name, &before, unix.AT_SYMLINK_NOFOLLOW); err != nil {
		return SymlinkArtifact{}, err
	}
	if before.Mode&unix.S_IFMT != unix.S_IFLNK || before.Uid != expectedUID ||
		before.Gid != expectedGID || before.Nlink != 1 || before.Ino == 0 {
		return SymlinkArtifact{}, fmt.Errorf("OpenRC WireGuard service link has an unsafe identity")
	}
	buffer := make([]byte, len(OpenRCServiceLinkTarget)+1)
	count, err := unix.Readlinkat(int(directory.file.Fd()), name, buffer)
	if err != nil {
		return SymlinkArtifact{}, fmt.Errorf("read OpenRC WireGuard service link: %w", err)
	}
	if count != len(OpenRCServiceLinkTarget) || string(buffer[:count]) != OpenRCServiceLinkTarget {
		return SymlinkArtifact{}, fmt.Errorf("OpenRC WireGuard service link has an unexpected target")
	}
	var after unix.Stat_t
	if err := unix.Fstatat(int(directory.file.Fd()), name, &after, unix.AT_SYMLINK_NOFOLLOW); err != nil ||
		before.Dev != after.Dev || before.Ino != after.Ino || before.Mode != after.Mode ||
		before.Uid != after.Uid || before.Gid != after.Gid || before.Nlink != after.Nlink {
		return SymlinkArtifact{}, fmt.Errorf("OpenRC WireGuard service link changed during attestation")
	}
	return SymlinkArtifact{
		Path: OpenRCServiceLinkPath, Target: OpenRCServiceLinkTarget,
		UID: after.Uid, GID: after.Gid, NLink: uint64(after.Nlink),
		Device: uint64(after.Dev), Inode: after.Ino,
	}, nil
}

// InspectOpenRCServiceLink returns the exact protected service-link identity.
// Absence is reported without creating or adopting any path.
func InspectOpenRCServiceLink(root string, expectedUID, expectedGID uint32) (SymlinkArtifact, bool, error) {
	directory, err := openPinnedDirectory(root, filepath.Dir(OpenRCServiceLinkPath), expectedUID, expectedGID)
	if err != nil {
		return SymlinkArtifact{}, false, err
	}
	defer func() { _ = directory.file.Close() }()
	artifact, err := captureSymlinkAt(
		directory, filepath.Base(OpenRCServiceLinkPath), expectedUID, expectedGID,
	)
	if errors.Is(err, unix.ENOENT) {
		return SymlinkArtifact{}, false, nil
	}
	if err != nil {
		return SymlinkArtifact{}, true, err
	}
	return artifact, true, nil
}

func sameSymlinkArtifact(left, right SymlinkArtifact) bool {
	return left == right
}

func validPlannedOrExactSymlink(artifact SymlinkArtifact, expectedUID, expectedGID uint32) bool {
	if artifact.Path != OpenRCServiceLinkPath || artifact.Target != OpenRCServiceLinkTarget ||
		artifact.UID != expectedUID || artifact.GID != expectedGID || artifact.NLink != 1 {
		return false
	}
	return (artifact.Device == 0 && artifact.Inode == 0) || artifact.Inode != 0
}

func sameArtifact(left, right Artifact) bool {
	return left == right
}

func reflectManifestArtifacts(artifacts []Artifact, journalEntries []journalArtifact) bool {
	if len(artifacts) != len(journalEntries) {
		return false
	}
	for index := range artifacts {
		if !sameArtifact(artifacts[index], journalEntries[index].Artifact) {
			return false
		}
	}
	return true
}

func reflectManifestOpenRCLink(manifest *SymlinkArtifact, journal *journalSymlink) bool {
	if manifest == nil || journal == nil {
		return manifest == nil && journal == nil
	}
	return journal.Artifact.Inode != 0 && sameSymlinkArtifact(*manifest, journal.Artifact)
}

func validateManifest(manifest *Manifest, expectedUID, expectedGID uint32) error {
	if manifest == nil || manifest.Schema != manifestSchema || len(manifest.Artifacts) != len(canonicalArtifactPaths) {
		return fmt.Errorf("invalid WireGuard ownership manifest envelope")
	}
	identities := make(map[[2]uint64]struct{}, len(manifest.Artifacts))
	for index, artifact := range manifest.Artifacts {
		if artifact.Path != canonicalArtifactPaths[index] {
			return fmt.Errorf("WireGuard ownership manifest has a noncanonical artifact inventory")
		}
		decoded, err := hex.DecodeString(artifact.SHA256)
		if err != nil || len(decoded) != sha256.Size || hex.EncodeToString(decoded) != artifact.SHA256 {
			return fmt.Errorf("WireGuard ownership manifest has an invalid SHA-256 digest for %s", artifact.Path)
		}
		if artifact.Mode != uint32(0600) || artifact.UID != expectedUID || artifact.GID != expectedGID ||
			artifact.NLink != 1 || artifact.Inode == 0 {
			return fmt.Errorf("WireGuard ownership manifest has invalid metadata for %s", artifact.Path)
		}
		identity := [2]uint64{artifact.Device, artifact.Inode}
		if _, duplicate := identities[identity]; duplicate {
			return fmt.Errorf("WireGuard ownership manifest aliases generated artifacts")
		}
		identities[identity] = struct{}{}
	}
	if manifest.OpenRCServiceLink != nil {
		link := *manifest.OpenRCServiceLink
		if !validPlannedOrExactSymlink(link, expectedUID, expectedGID) || link.Inode == 0 {
			return fmt.Errorf("WireGuard ownership manifest has invalid OpenRC service-link provenance")
		}
	}
	return nil
}

func canonicalManifestBytes(manifest Manifest, expectedUID, expectedGID uint32) ([]byte, error) {
	if err := validateManifest(&manifest, expectedUID, expectedGID); err != nil {
		return nil, err
	}
	wire, err := json.MarshalIndent(manifest, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("encode WireGuard ownership manifest: %w", err)
	}
	return append(wire, '\n'), nil
}

func plannedArtifact(path string, content []byte, expectedUID, expectedGID uint32) Artifact {
	digest := sha256.Sum256(content)
	return Artifact{
		Path: path, SHA256: hex.EncodeToString(digest[:]), Mode: uint32(0600),
		UID: expectedUID, GID: expectedGID, NLink: 1,
	}
}

func validPlannedOrExactArtifact(artifact Artifact, expectedPath string, expectedUID, expectedGID uint32) bool {
	decoded, err := hex.DecodeString(artifact.SHA256)
	if err != nil || len(decoded) != sha256.Size || hex.EncodeToString(decoded) != artifact.SHA256 {
		return false
	}
	if artifact.Path != expectedPath || artifact.Mode != uint32(0600) || artifact.UID != expectedUID ||
		artifact.GID != expectedGID || artifact.NLink != 1 {
		return false
	}
	return (artifact.Device == 0 && artifact.Inode == 0) || artifact.Inode != 0
}

func isRemovalOperation(operation string) bool {
	return operation == string(TransactionOperationRemove) ||
		operation == string(TransactionOperationRemovePendingReload)
}

func validateJournal(journal *transactionJournal, expectedUID, expectedGID uint32) error {
	if journal == nil || journal.Schema != transactionSchema ||
		(journal.Operation != string(TransactionOperationPublish) && !isRemovalOperation(journal.Operation)) ||
		len(journal.Artifacts) != len(canonicalArtifactPaths) {
		return fmt.Errorf("invalid WireGuard transaction journal envelope")
	}
	for index, entry := range journal.Artifacts {
		if !validPlannedOrExactArtifact(entry.Artifact, canonicalArtifactPaths[index], expectedUID, expectedGID) {
			return fmt.Errorf("invalid WireGuard transaction artifact %s", canonicalArtifactPaths[index])
		}
		if journal.Operation == string(TransactionOperationPublish) {
			expectedPrefix := "." + filepath.Base(entry.Artifact.Path) + ".syswarden-stage-"
			if filepath.Base(entry.StageName) != entry.StageName || !strings.HasPrefix(entry.StageName, expectedPrefix) ||
				len(entry.StageName) != len(expectedPrefix)+32 {
				return fmt.Errorf("invalid WireGuard transaction staging name for %s", entry.Artifact.Path)
			}
		} else if entry.StageName != "" {
			return fmt.Errorf("removal journal contains a staging name")
		}
		expectedQuarantinePrefix := "." + filepath.Base(entry.Artifact.Path) + ".syswarden-quarantine-"
		if filepath.Base(entry.QuarantineName) != entry.QuarantineName ||
			!strings.HasPrefix(entry.QuarantineName, expectedQuarantinePrefix) ||
			len(entry.QuarantineName) != len(expectedQuarantinePrefix)+32 {
			return fmt.Errorf("invalid WireGuard transaction quarantine name for %s", entry.Artifact.Path)
		}
	}
	if journal.Manifest != nil {
		if !validPlannedOrExactArtifact(journal.Manifest.Artifact, ManifestPath, expectedUID, expectedGID) {
			return fmt.Errorf("invalid WireGuard transaction manifest identity")
		}
		if journal.Operation == string(TransactionOperationPublish) {
			expectedPrefix := "." + filepath.Base(ManifestPath) + ".syswarden-stage-"
			if filepath.Base(journal.Manifest.StageName) != journal.Manifest.StageName ||
				!strings.HasPrefix(journal.Manifest.StageName, expectedPrefix) ||
				len(journal.Manifest.StageName) != len(expectedPrefix)+32 {
				return fmt.Errorf("invalid WireGuard transaction manifest staging name")
			}
		} else if journal.Manifest.StageName != "" {
			return fmt.Errorf("removal journal contains a manifest staging name")
		}
		expectedQuarantinePrefix := "." + filepath.Base(ManifestPath) + ".syswarden-quarantine-"
		if filepath.Base(journal.Manifest.QuarantineName) != journal.Manifest.QuarantineName ||
			!strings.HasPrefix(journal.Manifest.QuarantineName, expectedQuarantinePrefix) ||
			len(journal.Manifest.QuarantineName) != len(expectedQuarantinePrefix)+32 {
			return fmt.Errorf("invalid WireGuard transaction manifest quarantine name")
		}
	} else if isRemovalOperation(journal.Operation) {
		return fmt.Errorf("removal journal is missing the ownership manifest identity")
	}
	if journal.OpenRCServiceLink != nil {
		entry := journal.OpenRCServiceLink
		if !validPlannedOrExactSymlink(entry.Artifact, expectedUID, expectedGID) {
			return fmt.Errorf("invalid WireGuard transaction OpenRC service-link provenance")
		}
		expectedPrefix := "." + filepath.Base(OpenRCServiceLinkPath) + ".syswarden-quarantine-"
		if filepath.Base(entry.QuarantineName) != entry.QuarantineName ||
			!strings.HasPrefix(entry.QuarantineName, expectedPrefix) ||
			len(entry.QuarantineName) != len(expectedPrefix)+32 {
			return fmt.Errorf("invalid WireGuard transaction OpenRC service-link quarantine name")
		}
		if journal.Operation == string(TransactionOperationPublish) {
			expectedStagePrefix := "." + filepath.Base(OpenRCServiceLinkPath) + ".syswarden-stage-"
			if filepath.Base(entry.StageName) != entry.StageName ||
				!strings.HasPrefix(entry.StageName, expectedStagePrefix) ||
				len(entry.StageName) != len(expectedStagePrefix)+32 {
				return fmt.Errorf("invalid WireGuard transaction OpenRC service-link stage name")
			}
		} else if entry.StageName != "" {
			return fmt.Errorf("removal journal contains an OpenRC service-link stage name")
		}
	}
	return nil
}

func canonicalJournalBytes(journal transactionJournal, expectedUID, expectedGID uint32) ([]byte, error) {
	if err := validateJournal(&journal, expectedUID, expectedGID); err != nil {
		return nil, err
	}
	wire, err := json.MarshalIndent(journal, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("encode WireGuard transaction journal: %w", err)
	}
	return append(wire, '\n'), nil
}

func artifactMatchesPlan(actual, planned Artifact) bool {
	if planned.Device != 0 || planned.Inode != 0 {
		return sameArtifact(actual, planned)
	}
	return actual.Path == planned.Path && actual.SHA256 == planned.SHA256 && actual.Mode == planned.Mode &&
		actual.UID == planned.UID && actual.GID == planned.GID && actual.NLink == planned.NLink
}

func closeDirectories(entries []*stagedEntry) error {
	var result error
	for _, entry := range entries {
		if entry.directory == nil || entry.directory.file == nil {
			continue
		}
		if err := entry.directory.file.Close(); err != nil {
			result = errors.Join(result, err)
		}
		entry.directory.file = nil
	}
	return result
}

func stageEntry(root, logical, stageName, quarantineName string, content []byte, expectedUID, expectedGID uint32) (*stagedEntry, error) {
	if len(content) > maximumOwnedArtifactBytes {
		return nil, fmt.Errorf("owned artifact %s exceeds %d bytes", logical, maximumOwnedArtifactBytes)
	}
	directoryLogical := filepath.Dir(logical)
	directory, err := openPinnedDirectory(root, directoryLogical, expectedUID, expectedGID)
	if err != nil {
		return nil, err
	}
	finalName := filepath.Base(logical)
	record, err := writePrivateNamed(
		directory, stageName, logical, content,
		expectedUID, expectedGID, maximumOwnedArtifactBytes,
	)
	if err != nil {
		_ = directory.file.Close()
		return nil, fmt.Errorf("stage complete owned artifact %s: %w", logical, err)
	}
	return &stagedEntry{
		directory: directory,
		logical:   logical, finalName: finalName, stageName: stageName,
		quarantineName: quarantineName, record: record,
	}, nil
}

// StageOwnedArtifacts writes the exact three generated files to private,
// same-directory staging files. A durable bounded journal is published before
// the first private file is created so interrupted work can be recovered.
func StageOwnedArtifacts(root string, contents map[string][]byte, expectedUID, expectedGID uint32) (*StagedPublication, error) {
	if len(contents) != len(canonicalArtifactPaths) {
		return nil, fmt.Errorf("WireGuard staging requires the exact generated-artifact inventory")
	}
	if present, err := AnyOwnedArtifactExists(root); err != nil {
		return nil, err
	} else if present {
		return nil, fmt.Errorf("refusing to stage over an existing WireGuard generated artifact")
	}
	manifestHost, err := hostPath(root, ManifestPath)
	if err != nil {
		return nil, err
	}
	if _, err := os.Lstat(manifestHost); err == nil {
		return nil, fmt.Errorf("refusing to stage while a WireGuard ownership manifest exists")
	} else if !errors.Is(err, fs.ErrNotExist) {
		return nil, fmt.Errorf("inspect WireGuard ownership manifest before staging: %w", err)
	}

	journal := transactionJournal{
		Schema: transactionSchema, Operation: "publish",
		Artifacts: make([]journalArtifact, 0, len(canonicalArtifactPaths)),
	}
	for _, path := range canonicalArtifactPaths {
		content, ok := contents[path]
		if !ok {
			return nil, fmt.Errorf("WireGuard staging is missing %s", path)
		}
		stageName, err := randomTemporaryName(filepath.Base(path), "stage")
		if err != nil {
			return nil, err
		}
		quarantineName, err := randomTemporaryName(filepath.Base(path), "quarantine")
		if err != nil {
			return nil, err
		}
		journal.Artifacts = append(journal.Artifacts, journalArtifact{
			Artifact:       plannedArtifact(path, content, expectedUID, expectedGID),
			StageName:      stageName,
			QuarantineName: quarantineName,
		})
	}
	journalRecord, err := publishTransactionJournal(root, journal, expectedUID, expectedGID)
	if err != nil {
		return nil, err
	}
	publication := &StagedPublication{
		root: root, expectedUID: expectedUID, expectedGID: expectedGID,
		entries: make([]*stagedEntry, 0, len(canonicalArtifactPaths)+1),
		journal: journal, journalRecord: journalRecord,
	}
	for index, path := range canonicalArtifactPaths {
		entry, err := stageEntry(
			root, path, journal.Artifacts[index].StageName, journal.Artifacts[index].QuarantineName,
			contents[path], expectedUID, expectedGID,
		)
		if err != nil {
			rollbackErr := publication.Rollback()
			return nil, errors.Join(err, rollbackErr)
		}
		publication.entries = append(publication.entries, entry)
		publication.journal.Artifacts[index].Artifact = entry.record
		wireGuardStateFaultPoint(fmt.Sprintf("artifact-staged:%d", index))
	}
	updatedRecord, err := updateTransactionJournal(
		root, publication.journal, publication.journalRecord, expectedUID, expectedGID,
	)
	if err != nil {
		rollbackErr := publication.Rollback()
		return nil, errors.Join(err, rollbackErr)
	}
	publication.journalRecord = updatedRecord
	wireGuardStateFaultPoint("artifact-journal-updated")
	return publication, nil
}

// PlanOpenRCServiceLink durably records intent before SysWarden creates the
// fixed OpenRC instance link. Recovery can therefore remove an interrupted
// creation without adopting a link that predated the transaction.
func (publication *StagedPublication) PlanOpenRCServiceLink() error {
	if publication == nil || publication.closed || publication.committed ||
		publication.journal.OpenRCServiceLink != nil || publication.journal.Manifest != nil {
		return fmt.Errorf("staged publication cannot plan an OpenRC service link")
	}
	quarantineName, err := randomTemporaryName(filepath.Base(OpenRCServiceLinkPath), "quarantine")
	if err != nil {
		return err
	}
	stageName, err := randomTemporaryName(filepath.Base(OpenRCServiceLinkPath), "stage")
	if err != nil {
		return err
	}
	publication.journal.OpenRCServiceLink = &journalSymlink{
		Artifact: SymlinkArtifact{
			Path: OpenRCServiceLinkPath, Target: OpenRCServiceLinkTarget,
			UID: publication.expectedUID, GID: publication.expectedGID, NLink: 1,
		},
		StageName: stageName, QuarantineName: quarantineName,
	}
	updatedRecord, err := updateTransactionJournal(
		publication.root, publication.journal, publication.journalRecord,
		publication.expectedUID, publication.expectedGID,
	)
	if err != nil {
		publication.journal.OpenRCServiceLink = nil
		return fmt.Errorf("journal OpenRC service-link creation intent: %w", err)
	}
	publication.journalRecord = updatedRecord
	return nil
}

// CreateOpenRCServiceLink creates a private random stage, journals its exact
// inode, and only then publishes it with RENAME_NOREPLACE. EEXIST is not adopted.
func (publication *StagedPublication) CreateOpenRCServiceLink() (SymlinkArtifact, error) {
	if publication == nil || publication.closed || publication.committed ||
		publication.journal.OpenRCServiceLink == nil || publication.journal.Manifest != nil {
		return SymlinkArtifact{}, fmt.Errorf("staged publication has no active OpenRC service-link plan")
	}
	planned := publication.journal.OpenRCServiceLink.Artifact
	if planned.Inode != 0 {
		return SymlinkArtifact{}, fmt.Errorf("OpenRC service link is already captured")
	}
	directory, err := openPinnedDirectory(
		publication.root, filepath.Dir(OpenRCServiceLinkPath),
		publication.expectedUID, publication.expectedGID,
	)
	if err != nil {
		return SymlinkArtifact{}, err
	}
	defer func() { _ = directory.file.Close() }()
	entry := publication.journal.OpenRCServiceLink
	if err := unix.Symlinkat(OpenRCServiceLinkTarget, int(directory.file.Fd()), entry.StageName); err != nil {
		return SymlinkArtifact{}, fmt.Errorf("create private OpenRC service-link stage: %w", err)
	}
	if err := directory.file.Sync(); err != nil {
		return SymlinkArtifact{}, fmt.Errorf("sync private OpenRC service-link stage: %w", err)
	}
	wireGuardStateFaultPoint("openrc-link-staged")
	actual, err := captureSymlinkAt(
		directory, entry.StageName, publication.expectedUID, publication.expectedGID,
	)
	if err != nil {
		return SymlinkArtifact{}, fmt.Errorf("capture private OpenRC service-link stage: %w", err)
	}
	publication.journal.OpenRCServiceLink.Artifact = actual
	updatedRecord, err := updateTransactionJournal(
		publication.root, publication.journal, publication.journalRecord,
		publication.expectedUID, publication.expectedGID,
	)
	if err != nil {
		publication.journal.OpenRCServiceLink.Artifact = planned
		return SymlinkArtifact{}, fmt.Errorf("journal exact OpenRC service-link identity: %w", err)
	}
	publication.journalRecord = updatedRecord
	wireGuardStateFaultPoint("openrc-link-journal-updated")
	if err := unix.Renameat2(
		int(directory.file.Fd()), entry.StageName,
		int(directory.file.Fd()), filepath.Base(OpenRCServiceLinkPath),
		unix.RENAME_NOREPLACE,
	); err != nil {
		return SymlinkArtifact{}, fmt.Errorf("publish exact OpenRC service link: %w", err)
	}
	if err := directory.file.Sync(); err != nil {
		return SymlinkArtifact{}, fmt.Errorf("sync published OpenRC service link: %w", err)
	}
	published, err := captureSymlinkAt(
		directory, filepath.Base(OpenRCServiceLinkPath),
		publication.expectedUID, publication.expectedGID,
	)
	if err != nil || !sameSymlinkArtifact(published, actual) {
		if err == nil {
			err = fmt.Errorf("identity mismatch")
		}
		return SymlinkArtifact{}, fmt.Errorf("reattest published OpenRC service link: %w", err)
	}
	wireGuardStateFaultPoint("openrc-link-published")
	return actual, nil
}

// StageManifest prepares canonical manifest bytes inside this durable
// publication. The caller can reattest external state before Publish.
func (publication *StagedPublication) StageManifest(manifest Manifest) (*StagedManifest, error) {
	if publication == nil || publication.closed || publication.committed || publication.journal.Manifest != nil {
		return nil, fmt.Errorf("staged publication cannot accept a manifest")
	}
	if len(publication.entries) != len(canonicalArtifactPaths) {
		return nil, fmt.Errorf("staged publication has an incomplete artifact inventory")
	}
	for _, entry := range publication.entries {
		if !entry.published {
			return nil, fmt.Errorf("cannot stage ownership manifest before artifact publication")
		}
	}
	if !reflectManifestArtifacts(manifest.Artifacts, publication.journal.Artifacts) {
		return nil, fmt.Errorf("ownership manifest does not bind this publication")
	}
	if !reflectManifestOpenRCLink(manifest.OpenRCServiceLink, publication.journal.OpenRCServiceLink) {
		return nil, fmt.Errorf("ownership manifest does not bind the planned OpenRC service link")
	}
	wire, err := canonicalManifestBytes(manifest, publication.expectedUID, publication.expectedGID)
	if err != nil {
		return nil, err
	}
	stageName, err := randomTemporaryName(filepath.Base(ManifestPath), "stage")
	if err != nil {
		return nil, err
	}
	quarantineName, err := randomTemporaryName(filepath.Base(ManifestPath), "quarantine")
	if err != nil {
		return nil, err
	}
	publication.journal.Manifest = &journalArtifact{
		Artifact:       plannedArtifact(ManifestPath, wire, publication.expectedUID, publication.expectedGID),
		StageName:      stageName,
		QuarantineName: quarantineName,
	}
	updatedRecord, err := updateTransactionJournal(
		publication.root, publication.journal, publication.journalRecord,
		publication.expectedUID, publication.expectedGID,
	)
	if err != nil {
		publication.journal.Manifest = nil
		return nil, err
	}
	publication.journalRecord = updatedRecord
	entry, err := stageEntry(
		publication.root, ManifestPath, stageName, quarantineName, wire,
		publication.expectedUID, publication.expectedGID,
	)
	if err != nil {
		return nil, err
	}
	publication.entries = append(publication.entries, entry)
	publication.journal.Manifest.Artifact = entry.record
	wireGuardStateFaultPoint("manifest-staged")
	updatedRecord, err = updateTransactionJournal(
		publication.root, publication.journal, publication.journalRecord,
		publication.expectedUID, publication.expectedGID,
	)
	if err != nil {
		return nil, err
	}
	publication.journalRecord = updatedRecord
	wireGuardStateFaultPoint("manifest-journal-updated")
	return &StagedManifest{publication: publication, entry: entry}, nil
}

// Publish atomically renames every private stage into an absent final path.
// A partial publish is rolled back using exact inode-bound identities.
func (publication *StagedPublication) Publish() error {
	if publication == nil || publication.closed || publication.committed || len(publication.entries) == 0 {
		return fmt.Errorf("staged publication is not active")
	}
	for _, entry := range publication.entries {
		var stat unix.Stat_t
		err := unix.Fstatat(int(entry.directory.file.Fd()), entry.finalName, &stat, unix.AT_SYMLINK_NOFOLLOW)
		if err == nil {
			return fmt.Errorf("refusing to replace existing owned artifact %s", entry.logical)
		}
		if !errors.Is(err, unix.ENOENT) {
			return fmt.Errorf("inspect final owned artifact %s: %w", entry.logical, err)
		}
	}
	for index, entry := range publication.entries {
		if err := unix.Renameat2(
			int(entry.directory.file.Fd()), entry.stageName,
			int(entry.directory.file.Fd()), entry.finalName,
			unix.RENAME_NOREPLACE,
		); err != nil {
			rollbackErr := publication.rollbackEntries()
			return errors.Join(fmt.Errorf("publish owned artifact %s: %w", entry.logical, err), rollbackErr)
		}
		entry.published = true
		actual, _, err := captureAt(entry.directory, entry.finalName, entry.logical, entry.record.UID, entry.record.GID, maximumOwnedArtifactBytes)
		if err != nil || !sameArtifact(actual, entry.record) {
			rollbackErr := publication.rollbackEntries()
			if err != nil {
				return errors.Join(fmt.Errorf("reattest published artifact %s: %w", entry.logical, err), rollbackErr)
			}
			return errors.Join(fmt.Errorf("published artifact %s changed identity", entry.logical), rollbackErr)
		}
		if err := entry.directory.file.Sync(); err != nil {
			rollbackErr := publication.rollbackEntries()
			return errors.Join(fmt.Errorf("sync published artifact directory for %s: %w", entry.logical, err), rollbackErr)
		}
		wireGuardStateFaultPoint(fmt.Sprintf("artifact-published:%d", index))
	}
	return nil
}

// Publish atomically installs the ownership manifest as the durable completion
// marker for its parent publication.
func (manifest *StagedManifest) Publish() error {
	if manifest == nil || manifest.publication == nil || manifest.entry == nil ||
		manifest.publication.closed || manifest.publication.committed || manifest.entry.published {
		return fmt.Errorf("staged manifest is not active")
	}
	entry := manifest.entry
	var stat unix.Stat_t
	err := unix.Fstatat(int(entry.directory.file.Fd()), entry.finalName, &stat, unix.AT_SYMLINK_NOFOLLOW)
	if err == nil {
		return fmt.Errorf("refusing to replace existing owned artifact %s", entry.logical)
	}
	if !errors.Is(err, unix.ENOENT) {
		return fmt.Errorf("inspect final owned artifact %s: %w", entry.logical, err)
	}
	if err := unix.Renameat2(
		int(entry.directory.file.Fd()), entry.stageName,
		int(entry.directory.file.Fd()), entry.finalName,
		unix.RENAME_NOREPLACE,
	); err != nil {
		return fmt.Errorf("publish owned artifact %s: %w", entry.logical, err)
	}
	entry.published = true
	actual, _, err := captureAt(
		entry.directory, entry.finalName, entry.logical,
		entry.record.UID, entry.record.GID, maximumOwnershipManifestSize,
	)
	if err != nil || !sameArtifact(actual, entry.record) {
		if err != nil {
			return fmt.Errorf("reattest published artifact %s: %w", entry.logical, err)
		}
		return fmt.Errorf("published artifact %s changed identity", entry.logical)
	}
	if err := entry.directory.file.Sync(); err != nil {
		return fmt.Errorf("sync published artifact directory for %s: %w", entry.logical, err)
	}
	wireGuardStateFaultPoint("manifest-published")
	return nil
}

func (publication *StagedPublication) rollbackEntries() error {
	var result error
	for index := len(publication.entries) - 1; index >= 0; index-- {
		entry := publication.entries[index]
		name := entry.stageName
		if entry.published {
			name = entry.finalName
		}
		limit := int64(maximumOwnedArtifactBytes)
		if entry.logical == ManifestPath {
			limit = maximumOwnershipManifestSize
		}
		if err := removeExactAt(
			entry.directory, name, entry.quarantineName, entry.record,
			entry.record.UID, entry.record.GID, limit,
		); err != nil {
			result = errors.Join(result, fmt.Errorf("rollback owned artifact %s: %w", entry.logical, err))
		}
		entry.published = false
	}
	return result
}

// Rollback removes only unchanged staged or newly published identities.
func (publication *StagedPublication) Rollback() error {
	if publication == nil || publication.closed || publication.committed {
		return nil
	}
	result := closeDirectories(publication.entries)
	publication.closed = true
	_, recoveryErr := Recover(publication.root, publication.expectedUID, publication.expectedGID)
	return errors.Join(result, recoveryErr)
}

// Commit verifies the completed state, removes the durable transaction journal,
// and releases staging handles while retaining the published files.
func (publication *StagedPublication) Commit() error {
	if publication == nil || publication.closed || publication.committed || len(publication.entries) == 0 {
		return fmt.Errorf("staged publication is not active")
	}
	if publication.journal.Manifest == nil || len(publication.entries) != len(canonicalArtifactPaths)+1 {
		return fmt.Errorf("cannot commit publication without its ownership manifest")
	}
	for _, entry := range publication.entries {
		if !entry.published {
			return fmt.Errorf("cannot commit unpublished artifact %s", entry.logical)
		}
	}
	manifest, manifestRecord, err := readManifestWithRecord(
		publication.root, publication.expectedUID, publication.expectedGID,
	)
	if err != nil {
		return fmt.Errorf("verify ownership manifest before commit: %w", err)
	}
	if !sameArtifact(manifestRecord, publication.journal.Manifest.Artifact) ||
		!reflectManifestArtifacts(manifest.Artifacts, publication.journal.Artifacts) ||
		!reflectManifestOpenRCLink(manifest.OpenRCServiceLink, publication.journal.OpenRCServiceLink) {
		return fmt.Errorf("ownership manifest does not complete its transaction")
	}
	if err := VerifyManifest(publication.root, manifest, publication.expectedUID, publication.expectedGID); err != nil {
		return fmt.Errorf("verify generated artifacts before commit: %w", err)
	}
	if err := closeDirectories(publication.entries); err != nil {
		return fmt.Errorf("release WireGuard publication handles before commit: %w", err)
	}
	if err := removeTransactionJournal(
		publication.root, publication.journalRecord,
		publication.expectedUID, publication.expectedGID,
	); err != nil {
		return fmt.Errorf("complete WireGuard transaction journal: %w", err)
	}
	publication.committed = true
	publication.closed = true
	return nil
}

func captureLogical(root, logical string, expectedUID, expectedGID uint32, limit int64) (Artifact, []byte, error) {
	directory, err := openPinnedDirectory(root, filepath.Dir(logical), expectedUID, expectedGID)
	if err != nil {
		return Artifact{}, nil, err
	}
	defer func() { _ = directory.file.Close() }()
	return captureAt(directory, filepath.Base(logical), logical, expectedUID, expectedGID, limit)
}

func writePrivateNamed(
	directory *pinnedDirectory,
	name, logical string,
	content []byte,
	expectedUID, expectedGID uint32,
	limit int64,
) (Artifact, error) {
	if int64(len(content)) > limit {
		return Artifact{}, fmt.Errorf("private file %s exceeds %d bytes", logical, limit)
	}
	fd, err := unix.Openat(
		int(directory.file.Fd()), ".",
		unix.O_RDWR|unix.O_TMPFILE|unix.O_CLOEXEC,
		0600,
	)
	if err != nil {
		return Artifact{}, err
	}
	file := os.NewFile(uintptr(fd), logical)
	if file == nil {
		_ = unix.Close(fd)
		return Artifact{}, fmt.Errorf("open private transaction file %s", logical)
	}
	cleanup := func() {
		_ = file.Close()
	}
	if err := file.Chown(int(expectedUID), int(expectedGID)); err != nil {
		cleanup()
		return Artifact{}, err
	}
	if err := file.Chmod(0600); err != nil {
		cleanup()
		return Artifact{}, err
	}
	if _, err := file.Write(content); err != nil {
		cleanup()
		return Artifact{}, err
	}
	if err := file.Sync(); err != nil {
		cleanup()
		return Artifact{}, err
	}
	if err := unix.Linkat(int(file.Fd()), "", int(directory.file.Fd()), name, unix.AT_EMPTY_PATH); err != nil {
		cleanup()
		return Artifact{}, fmt.Errorf("link complete anonymous transaction file: %w", err)
	}
	if err := directory.file.Sync(); err != nil {
		cleanup()
		return Artifact{}, err
	}
	if err := file.Close(); err != nil {
		return Artifact{}, err
	}
	record, actual, err := captureAt(directory, name, logical, expectedUID, expectedGID, limit)
	if err != nil || !bytes.Equal(actual, content) {
		if err != nil {
			return Artifact{}, err
		}
		return Artifact{}, fmt.Errorf("private transaction file content mismatch")
	}
	return record, nil
}

func removeReservedTransactionScratch(
	directory *pinnedDirectory,
	name, quarantineName string,
	expectedUID, expectedGID uint32,
) (bool, error) {
	return removeReservedTransactionScratchForOperation(
		directory, name, quarantineName,
		expectedUID, expectedGID, TransactionOperationNone,
	)
}

func removeReservedTransactionScratchForOperation(
	directory *pinnedDirectory,
	name, quarantineName string,
	expectedUID, expectedGID uint32,
	requiredOperation TransactionOperation,
) (bool, error) {
	logical := filepath.Join(filepath.Dir(TransactionPath), name)
	record, wire, err := captureAt(directory, quarantineName, logical, expectedUID, expectedGID, maximumOwnershipManifestSize)
	if errors.Is(err, fs.ErrNotExist) {
		record, wire, err = captureAt(directory, name, logical, expectedUID, expectedGID, maximumOwnershipManifestSize)
		if errors.Is(err, fs.ErrNotExist) {
			return false, nil
		}
	}
	if err != nil {
		return true, fmt.Errorf("inspect reserved transaction scratch %s: %w", logical, err)
	}
	journal, err := decodeCanonicalJournal(wire, expectedUID, expectedGID)
	if err != nil {
		return true, fmt.Errorf("refusing to remove unowned transaction scratch %s: %w", logical, err)
	}
	if requiredOperation != TransactionOperationNone && TransactionOperation(journal.Operation) != requiredOperation {
		return true, fmt.Errorf(
			"refusing to remove %q transaction scratch while recovering %q", journal.Operation, requiredOperation,
		)
	}
	if err := removeExactAt(
		directory, name, quarantineName, record,
		expectedUID, expectedGID, maximumOwnershipManifestSize,
	); err != nil {
		return true, fmt.Errorf("remove reserved transaction scratch %s: %w", logical, err)
	}
	return true, nil
}

func publishTransactionJournal(root string, journal transactionJournal, expectedUID, expectedGID uint32) (Artifact, error) {
	wire, err := canonicalJournalBytes(journal, expectedUID, expectedGID)
	if err != nil {
		return Artifact{}, err
	}
	directory, err := openPinnedDirectory(root, filepath.Dir(TransactionPath), expectedUID, expectedGID)
	if err != nil {
		return Artifact{}, err
	}
	defer func() { _ = directory.file.Close() }()
	if _, err := removeReservedTransactionScratch(
		directory, transactionScratchName, transactionScratchQuarantine, expectedUID, expectedGID,
	); err != nil {
		return Artifact{}, err
	}
	if _, err := removeReservedTransactionScratch(
		directory, transactionNextName, transactionNextQuarantine, expectedUID, expectedGID,
	); err != nil {
		return Artifact{}, err
	}
	var quarantinedJournal unix.Stat_t
	if err := unix.Fstatat(
		int(directory.file.Fd()), transactionQuarantineName,
		&quarantinedJournal, unix.AT_SYMLINK_NOFOLLOW,
	); err == nil {
		return Artifact{}, fmt.Errorf("a quarantined WireGuard transaction journal requires recovery")
	} else if !errors.Is(err, unix.ENOENT) {
		return Artifact{}, fmt.Errorf("inspect quarantined WireGuard transaction journal: %w", err)
	}
	var existing unix.Stat_t
	if err := unix.Fstatat(int(directory.file.Fd()), filepath.Base(TransactionPath), &existing, unix.AT_SYMLINK_NOFOLLOW); err == nil {
		return Artifact{}, fmt.Errorf("a WireGuard transaction journal already exists")
	} else if !errors.Is(err, unix.ENOENT) {
		return Artifact{}, fmt.Errorf("inspect WireGuard transaction journal: %w", err)
	}
	if _, err := writePrivateNamed(
		directory, transactionScratchName, TransactionPath, wire,
		expectedUID, expectedGID, maximumOwnershipManifestSize,
	); err != nil {
		return Artifact{}, fmt.Errorf("stage WireGuard transaction journal: %w", err)
	}
	wireGuardStateFaultPoint("journal-initial-linked")
	if err := unix.Renameat2(
		int(directory.file.Fd()), transactionScratchName,
		int(directory.file.Fd()), filepath.Base(TransactionPath),
		unix.RENAME_NOREPLACE,
	); err != nil {
		return Artifact{}, fmt.Errorf("publish WireGuard transaction journal: %w", err)
	}
	if err := directory.file.Sync(); err != nil {
		return Artifact{}, fmt.Errorf("sync WireGuard transaction journal: %w", err)
	}
	record, actual, err := captureAt(directory, filepath.Base(TransactionPath), TransactionPath, expectedUID, expectedGID, maximumOwnershipManifestSize)
	if err != nil || !bytes.Equal(actual, wire) {
		if err != nil {
			return Artifact{}, err
		}
		return Artifact{}, fmt.Errorf("published WireGuard transaction journal mismatch")
	}
	return record, nil
}

func updateTransactionJournal(root string, journal transactionJournal, expectedRecord Artifact, expectedUID, expectedGID uint32) (Artifact, error) {
	wire, err := canonicalJournalBytes(journal, expectedUID, expectedGID)
	if err != nil {
		return Artifact{}, err
	}
	directory, err := openPinnedDirectory(root, filepath.Dir(TransactionPath), expectedUID, expectedGID)
	if err != nil {
		return Artifact{}, err
	}
	defer func() { _ = directory.file.Close() }()
	actualRecord, _, err := captureAt(directory, filepath.Base(TransactionPath), TransactionPath, expectedUID, expectedGID, maximumOwnershipManifestSize)
	if err != nil || !sameArtifact(actualRecord, expectedRecord) {
		if err == nil {
			err = fmt.Errorf("identity mismatch")
		}
		return Artifact{}, fmt.Errorf("reattest WireGuard transaction journal before update: %w", err)
	}
	if _, err := removeReservedTransactionScratch(
		directory, transactionNextName, transactionNextQuarantine, expectedUID, expectedGID,
	); err != nil {
		return Artifact{}, err
	}
	if _, err := writePrivateNamed(
		directory, transactionNextName, TransactionPath, wire,
		expectedUID, expectedGID, maximumOwnershipManifestSize,
	); err != nil {
		return Artifact{}, fmt.Errorf("stage WireGuard transaction journal update: %w", err)
	}
	wireGuardStateFaultPoint("journal-update-linked")
	if err := unix.Renameat2(
		int(directory.file.Fd()), transactionNextName,
		int(directory.file.Fd()), filepath.Base(TransactionPath),
		unix.RENAME_EXCHANGE,
	); err != nil {
		return Artifact{}, fmt.Errorf("exchange WireGuard transaction journal update: %w", err)
	}
	oldRecord, _, oldErr := captureAt(
		directory, transactionNextName, TransactionPath,
		expectedUID, expectedGID, maximumOwnershipManifestSize,
	)
	if oldErr != nil || !sameArtifact(oldRecord, expectedRecord) {
		restoreErr := unix.Renameat2(
			int(directory.file.Fd()), transactionNextName,
			int(directory.file.Fd()), filepath.Base(TransactionPath),
			unix.RENAME_EXCHANGE,
		)
		if oldErr == nil {
			oldErr = fmt.Errorf("identity mismatch")
		}
		return Artifact{}, errors.Join(fmt.Errorf("reattest exchanged transaction journal: %w", oldErr), restoreErr)
	}
	if err := directory.file.Sync(); err != nil {
		return Artifact{}, fmt.Errorf("sync WireGuard transaction journal update: %w", err)
	}
	wireGuardStateFaultPoint("journal-update-exchanged")
	record, actual, err := captureAt(directory, filepath.Base(TransactionPath), TransactionPath, expectedUID, expectedGID, maximumOwnershipManifestSize)
	if err != nil || !bytes.Equal(actual, wire) {
		if err != nil {
			return Artifact{}, err
		}
		return Artifact{}, fmt.Errorf("updated WireGuard transaction journal mismatch")
	}
	if _, err := removeReservedTransactionScratch(
		directory, transactionNextName, transactionNextQuarantine, expectedUID, expectedGID,
	); err != nil {
		return Artifact{}, fmt.Errorf("retire prior WireGuard transaction journal: %w", err)
	}
	return record, nil
}

func decodeCanonicalJournal(wire []byte, expectedUID, expectedGID uint32) (transactionJournal, error) {
	decoder := json.NewDecoder(bytes.NewReader(wire))
	decoder.DisallowUnknownFields()
	var journal transactionJournal
	if err := decoder.Decode(&journal); err != nil {
		return transactionJournal{}, fmt.Errorf("decode WireGuard transaction journal: %w", err)
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		return transactionJournal{}, fmt.Errorf("WireGuard transaction journal has trailing data")
	}
	canonical, err := canonicalJournalBytes(journal, expectedUID, expectedGID)
	if err != nil {
		return transactionJournal{}, err
	}
	if !bytes.Equal(wire, canonical) {
		return transactionJournal{}, fmt.Errorf("WireGuard transaction journal bytes are not canonical")
	}
	return journal, nil
}

func readTransactionJournal(root string, expectedUID, expectedGID uint32) (transactionJournal, Artifact, error) {
	record, wire, err := captureLogical(root, TransactionPath, expectedUID, expectedGID, maximumOwnershipManifestSize)
	if errors.Is(err, fs.ErrNotExist) {
		directory, openErr := openPinnedDirectory(root, filepath.Dir(TransactionPath), expectedUID, expectedGID)
		if openErr != nil {
			return transactionJournal{}, Artifact{}, openErr
		}
		record, wire, err = captureAt(
			directory, transactionQuarantineName, TransactionPath,
			expectedUID, expectedGID, maximumOwnershipManifestSize,
		)
		_ = directory.file.Close()
	}
	if err != nil {
		return transactionJournal{}, Artifact{}, err
	}
	journal, err := decodeCanonicalJournal(wire, expectedUID, expectedGID)
	if err != nil {
		return transactionJournal{}, Artifact{}, err
	}
	return journal, record, nil
}

type transactionLocationPair struct {
	logical        string
	name           string
	quarantineName string
}

func boundedTransactionLocations() []transactionLocationPair {
	return []transactionLocationPair{
		{
			logical: TransactionPath, name: filepath.Base(TransactionPath),
			quarantineName: transactionQuarantineName,
		},
		{
			logical: filepath.Join(filepath.Dir(TransactionPath), transactionScratchName),
			name:    transactionScratchName, quarantineName: transactionScratchQuarantine,
		},
		{
			logical: filepath.Join(filepath.Dir(TransactionPath), transactionNextName),
			name:    transactionNextName, quarantineName: transactionNextQuarantine,
		},
	}
}

// InspectTransaction verifies every present fixed journal location and reports
// one exact operation. Mixed, corrupt, unsafe, or ambiguous journals fail
// closed. The boolean is false only when every bounded journal path is absent.
func InspectTransaction(
	root string,
	expectedUID, expectedGID uint32,
) (TransactionOperation, bool, error) {
	inventory, err := Inspect(root)
	if err != nil {
		return TransactionOperationNone, false, err
	}
	if !inventory.Transaction {
		return TransactionOperationNone, false, nil
	}
	directory, err := openPinnedDirectory(root, filepath.Dir(TransactionPath), expectedUID, expectedGID)
	if err != nil {
		return TransactionOperationNone, true, err
	}
	defer func() { _ = directory.file.Close() }()

	operation := TransactionOperationNone
	present := false
	for _, pair := range boundedTransactionLocations() {
		pairPresent := 0
		for _, name := range []string{pair.name, pair.quarantineName} {
			_, wire, captureErr := captureAt(
				directory, name, pair.logical,
				expectedUID, expectedGID, maximumOwnershipManifestSize,
			)
			if errors.Is(captureErr, fs.ErrNotExist) {
				continue
			}
			if captureErr != nil {
				return TransactionOperationNone, true, fmt.Errorf(
					"inspect bounded WireGuard transaction location %s: %w", name, captureErr,
				)
			}
			pairPresent++
			journal, decodeErr := decodeCanonicalJournal(wire, expectedUID, expectedGID)
			if decodeErr != nil {
				return TransactionOperationNone, true, fmt.Errorf(
					"verify bounded WireGuard transaction location %s: %w", name, decodeErr,
				)
			}
			candidate := TransactionOperation(journal.Operation)
			if operation != TransactionOperationNone && candidate != operation {
				return TransactionOperationNone, true, fmt.Errorf(
					"mixed WireGuard transaction operations %q and %q", operation, candidate,
				)
			}
			operation = candidate
			present = true
		}
		if pairPresent > 1 {
			return TransactionOperationNone, true, fmt.Errorf(
				"both active and quarantined WireGuard transaction locations exist for %s", pair.logical,
			)
		}
	}
	if !present {
		return TransactionOperationNone, false, nil
	}
	return operation, true, nil
}

func removeTransactionJournal(root string, expected Artifact, expectedUID, expectedGID uint32) error {
	return removeExactLogical(root, expected, transactionQuarantineName, expectedUID, expectedGID)
}

// CaptureManifest records the exact current identities of all generated files.
func CaptureManifest(root string, expectedUID, expectedGID uint32) (Manifest, error) {
	manifest := Manifest{Schema: manifestSchema, Artifacts: make([]Artifact, 0, len(canonicalArtifactPaths))}
	for _, path := range canonicalArtifactPaths {
		record, _, err := captureLogical(root, path, expectedUID, expectedGID, maximumOwnedArtifactBytes)
		if err != nil {
			return Manifest{}, fmt.Errorf("capture WireGuard ownership for %s: %w", path, err)
		}
		manifest.Artifacts = append(manifest.Artifacts, record)
	}
	if err := validateManifest(&manifest, expectedUID, expectedGID); err != nil {
		return Manifest{}, err
	}
	return manifest, nil
}

func readManifestWithRecord(root string, expectedUID, expectedGID uint32) (Manifest, Artifact, error) {
	record, wire, err := captureLogical(root, ManifestPath, expectedUID, expectedGID, maximumOwnershipManifestSize)
	if err != nil {
		return Manifest{}, Artifact{}, fmt.Errorf("read WireGuard ownership manifest: %w", err)
	}
	decoder := json.NewDecoder(bytes.NewReader(wire))
	decoder.DisallowUnknownFields()
	var manifest Manifest
	if err := decoder.Decode(&manifest); err != nil {
		return Manifest{}, Artifact{}, fmt.Errorf("decode WireGuard ownership manifest: %w", err)
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		return Manifest{}, Artifact{}, fmt.Errorf("WireGuard ownership manifest has trailing data")
	}
	canonical, err := canonicalManifestBytes(manifest, expectedUID, expectedGID)
	if err != nil {
		return Manifest{}, Artifact{}, err
	}
	if !bytes.Equal(wire, canonical) {
		return Manifest{}, Artifact{}, fmt.Errorf("WireGuard ownership manifest bytes are not canonical")
	}
	return manifest, record, nil
}

// ReadManifest reads and validates the canonical manifest envelope and its own
// root-owned 0600 regular-file identity. It does not verify artifact contents.
func ReadManifest(root string, expectedUID, expectedGID uint32) (Manifest, error) {
	manifest, _, err := readManifestWithRecord(root, expectedUID, expectedGID)
	return manifest, err
}

// VerifyManifest binds the manifest to the exact current file identities,
// metadata, hard-link count, and SHA-256 content digests.
func VerifyManifest(root string, manifest Manifest, expectedUID, expectedGID uint32) error {
	if err := validateManifest(&manifest, expectedUID, expectedGID); err != nil {
		return err
	}
	for _, expected := range manifest.Artifacts {
		actual, _, err := captureLogical(root, expected.Path, expectedUID, expectedGID, maximumOwnedArtifactBytes)
		if err != nil {
			return fmt.Errorf("verify WireGuard owned artifact %s: %w", expected.Path, err)
		}
		if !sameArtifact(actual, expected) {
			return fmt.Errorf("WireGuard owned artifact %s does not match its ownership manifest", expected.Path)
		}
	}
	if manifest.OpenRCServiceLink != nil {
		actual, present, err := InspectOpenRCServiceLink(root, expectedUID, expectedGID)
		if err != nil || !present {
			if err == nil {
				err = fs.ErrNotExist
			}
			return fmt.Errorf("verify owned OpenRC WireGuard service link: %w", err)
		}
		if !sameSymlinkArtifact(actual, *manifest.OpenRCServiceLink) {
			return fmt.Errorf("owned OpenRC WireGuard service link does not match its ownership manifest")
		}
	}
	return nil
}

// ReadVerifiedArtifact returns content only when the requested path is one of
// the three canonical entries and still matches its manifest record exactly.
func ReadVerifiedArtifact(root string, manifest Manifest, logical string, expectedUID, expectedGID uint32) ([]byte, error) {
	if err := validateManifest(&manifest, expectedUID, expectedGID); err != nil {
		return nil, err
	}
	for _, expected := range manifest.Artifacts {
		if expected.Path != logical {
			continue
		}
		actual, content, err := captureLogical(root, logical, expectedUID, expectedGID, maximumOwnedArtifactBytes)
		if err != nil {
			return nil, fmt.Errorf("read WireGuard owned artifact %s: %w", logical, err)
		}
		if !sameArtifact(actual, expected) {
			return nil, fmt.Errorf("WireGuard owned artifact %s does not match its ownership manifest", logical)
		}
		return content, nil
	}
	return nil, fmt.Errorf("path %s is not in the WireGuard ownership manifest", logical)
}

// ReadAndVerify reads the manifest and verifies every exact generated artifact.
func ReadAndVerify(root string, expectedUID, expectedGID uint32) (Manifest, error) {
	manifest, err := ReadManifest(root, expectedUID, expectedGID)
	if err != nil {
		return Manifest{}, err
	}
	if err := VerifyManifest(root, manifest, expectedUID, expectedGID); err != nil {
		return Manifest{}, err
	}
	return manifest, nil
}

// AnyOwnedArtifactExists reports whether any exact generated final path exists.
// Symlinks and other unsafe types still count as existing and are never followed.
func AnyOwnedArtifactExists(root string) (bool, error) {
	for _, logical := range canonicalArtifactPaths {
		host, err := hostPath(root, logical)
		if err != nil {
			return false, err
		}
		if _, err := os.Lstat(host); err == nil {
			return true, nil
		} else if !errors.Is(err, fs.ErrNotExist) {
			return false, fmt.Errorf("inspect generated artifact %s: %w", logical, err)
		}
	}
	return false, nil
}

// Inspect returns a bounded no-follow inventory. Unsafe file types still count
// as present so callers cannot misclassify partial or hostile state as absent.
func Inspect(root string) (Inventory, error) {
	var inventory Inventory
	for _, logical := range canonicalArtifactPaths {
		host, err := hostPath(root, logical)
		if err != nil {
			return Inventory{}, err
		}
		if _, err := os.Lstat(host); err == nil {
			inventory.Artifacts = append(inventory.Artifacts, logical)
		} else if !errors.Is(err, fs.ErrNotExist) {
			return Inventory{}, fmt.Errorf("inspect WireGuard state path %s: %w", logical, err)
		}
	}
	manifestHost, err := hostPath(root, ManifestPath)
	if err != nil {
		return Inventory{}, err
	}
	if _, err := os.Lstat(manifestHost); err == nil {
		inventory.Manifest = true
	} else if !errors.Is(err, fs.ErrNotExist) {
		return Inventory{}, fmt.Errorf("inspect WireGuard state path %s: %w", ManifestPath, err)
	}
	transactionLogicals := []string{
		TransactionPath,
		filepath.Join(filepath.Dir(TransactionPath), transactionScratchName),
		filepath.Join(filepath.Dir(TransactionPath), transactionNextName),
		filepath.Join(filepath.Dir(TransactionPath), transactionQuarantineName),
		filepath.Join(filepath.Dir(TransactionPath), transactionScratchQuarantine),
		filepath.Join(filepath.Dir(TransactionPath), transactionNextQuarantine),
	}
	for _, logical := range transactionLogicals {
		host, err := hostPath(root, logical)
		if err != nil {
			return Inventory{}, err
		}
		if _, err := os.Lstat(host); err == nil {
			inventory.Transaction = true
		} else if !errors.Is(err, fs.ErrNotExist) {
			return Inventory{}, fmt.Errorf("inspect WireGuard state path %s: %w", logical, err)
		}
	}
	return inventory, nil
}

func removeExactAt(
	directory *pinnedDirectory,
	name, quarantineName string,
	expected Artifact,
	expectedUID, expectedGID uint32,
	limit int64,
) error {
	quarantined, _, quarantineErr := captureAt(
		directory, quarantineName, expected.Path, expectedUID, expectedGID, limit,
	)
	if quarantineErr == nil {
		var finalStat unix.Stat_t
		if err := unix.Fstatat(int(directory.file.Fd()), name, &finalStat, unix.AT_SYMLINK_NOFOLLOW); err == nil {
			return fmt.Errorf("both final and quarantine paths exist for %s", expected.Path)
		} else if !errors.Is(err, unix.ENOENT) {
			return fmt.Errorf("inspect final path while resuming removal of %s: %w", expected.Path, err)
		}
		if !sameArtifact(quarantined, expected) {
			if err := unix.Renameat2(
				int(directory.file.Fd()), quarantineName,
				int(directory.file.Fd()), name,
				unix.RENAME_NOREPLACE,
			); err != nil {
				return fmt.Errorf("restore changed quarantine for %s: %w", expected.Path, err)
			}
			_ = directory.file.Sync()
			return fmt.Errorf("refusing to remove changed quarantined artifact %s", expected.Path)
		}
	} else if !errors.Is(quarantineErr, fs.ErrNotExist) {
		return fmt.Errorf("inspect quarantine for %s: %w", expected.Path, quarantineErr)
	} else {
		actual, _, err := captureAt(directory, name, expected.Path, expectedUID, expectedGID, limit)
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		if err != nil {
			return err
		}
		if !sameArtifact(actual, expected) {
			return fmt.Errorf("refusing to remove changed owned artifact %s", expected.Path)
		}
		wireGuardStateFaultPoint("remove-before-rename:" + expected.Path)
		if err := unix.Renameat2(
			int(directory.file.Fd()), name,
			int(directory.file.Fd()), quarantineName,
			unix.RENAME_NOREPLACE,
		); err != nil {
			return fmt.Errorf("quarantine owned artifact %s: %w", expected.Path, err)
		}
		if err := directory.file.Sync(); err != nil {
			return fmt.Errorf("sync quarantine for %s: %w", expected.Path, err)
		}
		wireGuardStateFaultPoint("remove-renamed:" + expected.Path)
		quarantined, _, err = captureAt(
			directory, quarantineName, expected.Path, expectedUID, expectedGID, limit,
		)
		if err != nil || !sameArtifact(quarantined, expected) {
			restoreErr := unix.Renameat2(
				int(directory.file.Fd()), quarantineName,
				int(directory.file.Fd()), name,
				unix.RENAME_NOREPLACE,
			)
			if err == nil {
				err = fmt.Errorf("identity mismatch")
			}
			return errors.Join(fmt.Errorf("reattest quarantined artifact %s: %w", expected.Path, err), restoreErr)
		}
	}
	wireGuardStateFaultPoint("remove-before-unlink:" + expected.Path)
	finalQuarantine, _, err := captureAt(
		directory, quarantineName, expected.Path, expectedUID, expectedGID, limit,
	)
	if err != nil || !sameArtifact(finalQuarantine, expected) {
		var finalStat unix.Stat_t
		finalErr := unix.Fstatat(
			int(directory.file.Fd()), name, &finalStat, unix.AT_SYMLINK_NOFOLLOW,
		)
		var restoreErr error
		if errors.Is(finalErr, unix.ENOENT) {
			restoreErr = unix.Renameat2(
				int(directory.file.Fd()), quarantineName,
				int(directory.file.Fd()), name,
				unix.RENAME_NOREPLACE,
			)
			if restoreErr == nil {
				restoreErr = directory.file.Sync()
			}
		} else if finalErr != nil {
			restoreErr = fmt.Errorf("inspect final path before quarantine restoration: %w", finalErr)
		}
		if err == nil {
			err = fmt.Errorf("identity mismatch")
		}
		return errors.Join(
			fmt.Errorf("refusing to unlink changed quarantined artifact %s: %w", expected.Path, err),
			restoreErr,
		)
	}
	if err := unix.Unlinkat(int(directory.file.Fd()), quarantineName, 0); err != nil {
		return fmt.Errorf("remove quarantined owned artifact %s: %w", expected.Path, err)
	}
	if err := directory.file.Sync(); err != nil {
		return err
	}
	wireGuardStateFaultPoint("remove-unlinked:" + expected.Path)
	return nil
}

func symlinkMatchesPlan(actual, planned SymlinkArtifact) bool {
	if planned.Device != 0 || planned.Inode != 0 {
		return sameSymlinkArtifact(actual, planned)
	}
	return actual.Path == planned.Path && actual.Target == planned.Target &&
		actual.UID == planned.UID && actual.GID == planned.GID && actual.NLink == planned.NLink
}

func restoreChangedSymlinkQuarantine(
	directory *pinnedDirectory,
	name, quarantineName string,
) error {
	var finalStat unix.Stat_t
	if err := unix.Fstatat(
		int(directory.file.Fd()), name, &finalStat, unix.AT_SYMLINK_NOFOLLOW,
	); err == nil {
		return fmt.Errorf("public OpenRC service-link path is already occupied")
	} else if !errors.Is(err, unix.ENOENT) {
		return fmt.Errorf("inspect public OpenRC service-link path before restoration: %w", err)
	}
	if err := unix.Renameat2(
		int(directory.file.Fd()), quarantineName,
		int(directory.file.Fd()), name,
		unix.RENAME_NOREPLACE,
	); err != nil {
		return fmt.Errorf("restore changed OpenRC service-link quarantine: %w", err)
	}
	if err := directory.file.Sync(); err != nil {
		return fmt.Errorf("sync restored OpenRC service-link quarantine: %w", err)
	}
	return nil
}

func removeExactSymlinkAt(
	directory *pinnedDirectory,
	name, quarantineName string,
	expected SymlinkArtifact,
	expectedUID, expectedGID uint32,
) error {
	quarantined, quarantineErr := captureSymlinkAt(directory, quarantineName, expectedUID, expectedGID)
	if quarantineErr == nil {
		var finalStat unix.Stat_t
		if err := unix.Fstatat(int(directory.file.Fd()), name, &finalStat, unix.AT_SYMLINK_NOFOLLOW); err == nil {
			return fmt.Errorf("both final and quarantine paths exist for %s", expected.Path)
		} else if !errors.Is(err, unix.ENOENT) {
			return fmt.Errorf("inspect final OpenRC service-link path: %w", err)
		}
		if !sameSymlinkArtifact(quarantined, expected) {
			restoreErr := restoreChangedSymlinkQuarantine(directory, name, quarantineName)
			return errors.Join(
				fmt.Errorf("refusing to remove changed quarantined OpenRC service link"),
				restoreErr,
			)
		}
	} else if !errors.Is(quarantineErr, unix.ENOENT) {
		return fmt.Errorf("inspect quarantined OpenRC service link: %w", quarantineErr)
	} else {
		actual, err := captureSymlinkAt(directory, name, expectedUID, expectedGID)
		if errors.Is(err, unix.ENOENT) {
			return nil
		}
		if err != nil || !sameSymlinkArtifact(actual, expected) {
			if err == nil {
				err = fmt.Errorf("identity mismatch")
			}
			return fmt.Errorf("refusing to remove changed OpenRC service link: %w", err)
		}
		wireGuardStateFaultPoint("remove-before-rename:" + OpenRCServiceLinkPath)
		if err := unix.Renameat2(
			int(directory.file.Fd()), name,
			int(directory.file.Fd()), quarantineName,
			unix.RENAME_NOREPLACE,
		); err != nil {
			return fmt.Errorf("quarantine owned OpenRC service link: %w", err)
		}
		if err := directory.file.Sync(); err != nil {
			return fmt.Errorf("sync quarantined OpenRC service link: %w", err)
		}
		wireGuardStateFaultPoint("remove-renamed:" + OpenRCServiceLinkPath)
		quarantined, err = captureSymlinkAt(directory, quarantineName, expectedUID, expectedGID)
		if err != nil || !sameSymlinkArtifact(quarantined, expected) {
			restoreErr := unix.Renameat2(
				int(directory.file.Fd()), quarantineName,
				int(directory.file.Fd()), name,
				unix.RENAME_NOREPLACE,
			)
			if err == nil {
				err = fmt.Errorf("identity mismatch")
			}
			return errors.Join(fmt.Errorf("reattest quarantined OpenRC service link: %w", err), restoreErr)
		}
	}
	wireGuardStateFaultPoint("remove-before-unlink:" + OpenRCServiceLinkPath)
	finalQuarantine, err := captureSymlinkAt(directory, quarantineName, expectedUID, expectedGID)
	if err != nil || !sameSymlinkArtifact(finalQuarantine, expected) {
		if err == nil {
			err = fmt.Errorf("identity mismatch")
		}
		restoreErr := restoreChangedSymlinkQuarantine(directory, name, quarantineName)
		return errors.Join(
			fmt.Errorf("refusing to unlink changed quarantined OpenRC service link: %w", err),
			restoreErr,
		)
	}
	if err := unix.Unlinkat(int(directory.file.Fd()), quarantineName, 0); err != nil {
		return fmt.Errorf("remove quarantined OpenRC service link: %w", err)
	}
	if err := directory.file.Sync(); err != nil {
		return err
	}
	wireGuardStateFaultPoint("remove-unlinked:" + OpenRCServiceLinkPath)
	return nil
}

func removeJournalSymlink(
	root string,
	entry journalSymlink,
	staging bool,
	expectedUID, expectedGID uint32,
) error {
	name := filepath.Base(OpenRCServiceLinkPath)
	if staging {
		if entry.StageName == "" {
			return nil
		}
		name = entry.StageName
	} else if entry.Artifact.Inode == 0 {
		// A planned-only journal never proves ownership of the public final name.
		return nil
	}
	directory, err := openPinnedDirectory(root, filepath.Dir(OpenRCServiceLinkPath), expectedUID, expectedGID)
	if err != nil {
		return err
	}
	defer func() { _ = directory.file.Close() }()
	quarantined, quarantineErr := captureSymlinkAt(
		directory, entry.QuarantineName, expectedUID, expectedGID,
	)
	if quarantineErr == nil {
		if !symlinkMatchesPlan(quarantined, entry.Artifact) {
			return fmt.Errorf("refusing to recover changed OpenRC service-link quarantine")
		}
		return removeExactSymlinkAt(
			directory, name, entry.QuarantineName,
			quarantined, expectedUID, expectedGID,
		)
	}
	if !errors.Is(quarantineErr, unix.ENOENT) {
		return fmt.Errorf("inspect recoverable OpenRC service-link quarantine: %w", quarantineErr)
	}
	actual, err := captureSymlinkAt(
		directory, name, expectedUID, expectedGID,
	)
	if errors.Is(err, unix.ENOENT) {
		return nil
	}
	if err != nil || !symlinkMatchesPlan(actual, entry.Artifact) {
		if err == nil {
			err = fmt.Errorf("identity mismatch")
		}
		return fmt.Errorf("refusing to recover changed OpenRC service link: %w", err)
	}
	return removeExactSymlinkAt(
		directory, name, entry.QuarantineName,
		actual, expectedUID, expectedGID,
	)
}

func journalSymlinkStageExists(
	root string,
	entry journalSymlink,
	expectedUID, expectedGID uint32,
) (bool, error) {
	if entry.StageName == "" {
		return false, nil
	}
	directory, err := openPinnedDirectory(root, filepath.Dir(OpenRCServiceLinkPath), expectedUID, expectedGID)
	if err != nil {
		return false, err
	}
	defer func() { _ = directory.file.Close() }()
	actual, err := captureSymlinkAt(directory, entry.StageName, expectedUID, expectedGID)
	if errors.Is(err, unix.ENOENT) {
		return false, nil
	}
	if err != nil {
		return true, fmt.Errorf("inspect journaled OpenRC service-link stage: %w", err)
	}
	if !symlinkMatchesPlan(actual, entry.Artifact) {
		return true, fmt.Errorf("journaled OpenRC service-link stage changed identity")
	}
	return true, nil
}

func removeExactLogical(root string, expected Artifact, quarantineName string, expectedUID, expectedGID uint32) error {
	directory, err := openPinnedDirectory(root, filepath.Dir(expected.Path), expectedUID, expectedGID)
	if err != nil {
		return err
	}
	defer func() { _ = directory.file.Close() }()
	limit := int64(maximumOwnedArtifactBytes)
	if expected.Path == ManifestPath || expected.Path == TransactionPath {
		limit = maximumOwnershipManifestSize
	}
	return removeExactAt(directory, filepath.Base(expected.Path), quarantineName, expected, expectedUID, expectedGID, limit)
}

func removeJournalLocation(root string, entry journalArtifact, staging bool, expectedUID, expectedGID uint32) error {
	name := filepath.Base(entry.Artifact.Path)
	if staging {
		if entry.StageName == "" {
			return nil
		}
		name = entry.StageName
	}
	directory, err := openPinnedDirectory(root, filepath.Dir(entry.Artifact.Path), expectedUID, expectedGID)
	if err != nil {
		return err
	}
	defer func() { _ = directory.file.Close() }()
	limit := int64(maximumOwnedArtifactBytes)
	if entry.Artifact.Path == ManifestPath {
		limit = maximumOwnershipManifestSize
	}
	quarantined, _, quarantineErr := captureAt(
		directory, entry.QuarantineName, entry.Artifact.Path,
		expectedUID, expectedGID, limit,
	)
	if quarantineErr == nil {
		if !artifactMatchesPlan(quarantined, entry.Artifact) {
			return fmt.Errorf("refusing to recover changed WireGuard quarantine %s", entry.Artifact.Path)
		}
		return removeExactAt(
			directory, name, entry.QuarantineName, quarantined,
			expectedUID, expectedGID, limit,
		)
	}
	if !errors.Is(quarantineErr, fs.ErrNotExist) {
		return fmt.Errorf("inspect recoverable WireGuard quarantine %s: %w", entry.Artifact.Path, quarantineErr)
	}
	actual, _, err := captureAt(directory, name, entry.Artifact.Path, expectedUID, expectedGID, limit)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("inspect recoverable WireGuard artifact %s: %w", entry.Artifact.Path, err)
	}
	if !artifactMatchesPlan(actual, entry.Artifact) {
		return fmt.Errorf("refusing to recover changed WireGuard artifact %s", entry.Artifact.Path)
	}
	return removeExactAt(directory, name, entry.QuarantineName, actual, expectedUID, expectedGID, limit)
}

func manifestCompletesJournal(root string, journal transactionJournal, expectedUID, expectedGID uint32) (bool, error) {
	if journal.Manifest == nil {
		return false, nil
	}
	manifest, manifestRecord, err := readManifestWithRecord(root, expectedUID, expectedGID)
	if errors.Is(err, fs.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, nil
	}
	if !artifactMatchesPlan(manifestRecord, journal.Manifest.Artifact) ||
		!reflectManifestArtifacts(manifest.Artifacts, journal.Artifacts) ||
		!reflectManifestOpenRCLink(manifest.OpenRCServiceLink, journal.OpenRCServiceLink) {
		return false, fmt.Errorf("published WireGuard manifest does not match its transaction journal")
	}
	if err := VerifyManifest(root, manifest, expectedUID, expectedGID); err != nil {
		return false, nil
	}
	return true, nil
}

func recoverPublishTransaction(root string, journal transactionJournal, journalRecord Artifact, expectedUID, expectedGID uint32) error {
	complete, err := manifestCompletesJournal(root, journal, expectedUID, expectedGID)
	if err != nil {
		return err
	}
	if complete {
		for _, entry := range journal.Artifacts {
			if err := removeJournalLocation(root, entry, true, expectedUID, expectedGID); err != nil {
				return err
			}
		}
		if journal.Manifest != nil {
			if err := removeJournalLocation(root, *journal.Manifest, true, expectedUID, expectedGID); err != nil {
				return err
			}
		}
		if journal.OpenRCServiceLink != nil {
			if err := removeJournalSymlink(
				root, *journal.OpenRCServiceLink, true, expectedUID, expectedGID,
			); err != nil {
				return err
			}
		}
		return removeTransactionJournal(root, journalRecord, expectedUID, expectedGID)
	}
	if journal.OpenRCServiceLink != nil {
		stagePresent, err := journalSymlinkStageExists(
			root, *journal.OpenRCServiceLink, expectedUID, expectedGID,
		)
		if err != nil {
			return err
		}
		if stagePresent {
			if err := removeJournalSymlink(
				root, *journal.OpenRCServiceLink, true, expectedUID, expectedGID,
			); err != nil {
				return err
			}
		} else if journal.OpenRCServiceLink.Artifact.Inode != 0 {
			if err := removeJournalSymlink(
				root, *journal.OpenRCServiceLink, false, expectedUID, expectedGID,
			); err != nil {
				return err
			}
		}
	}

	if journal.Manifest != nil {
		if err := removeJournalLocation(root, *journal.Manifest, false, expectedUID, expectedGID); err != nil {
			return err
		}
		if err := removeJournalLocation(root, *journal.Manifest, true, expectedUID, expectedGID); err != nil {
			return err
		}
	} else {
		manifestHost, err := hostPath(root, ManifestPath)
		if err != nil {
			return err
		}
		if _, err := os.Lstat(manifestHost); err == nil {
			return fmt.Errorf("an unjournaled WireGuard ownership manifest blocks publication recovery")
		} else if !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("inspect WireGuard ownership manifest during recovery: %w", err)
		}
	}
	for _, entry := range journal.Artifacts {
		if err := removeJournalLocation(root, entry, false, expectedUID, expectedGID); err != nil {
			return err
		}
		if err := removeJournalLocation(root, entry, true, expectedUID, expectedGID); err != nil {
			return err
		}
	}
	return removeTransactionJournal(root, journalRecord, expectedUID, expectedGID)
}

func recoverRemovalTransaction(
	root string,
	journal transactionJournal,
	journalRecord Artifact,
	expectedUID, expectedGID uint32,
	retainReloadDebt bool,
) error {
	if journal.OpenRCServiceLink != nil {
		if err := removeJournalSymlink(
			root, *journal.OpenRCServiceLink, false, expectedUID, expectedGID,
		); err != nil {
			return err
		}
	}
	for _, entry := range journal.Artifacts {
		if err := removeJournalLocation(root, entry, false, expectedUID, expectedGID); err != nil {
			return err
		}
	}
	if journal.Manifest == nil {
		return fmt.Errorf("removal journal is missing its ownership manifest identity")
	}
	if err := removeJournalLocation(root, *journal.Manifest, false, expectedUID, expectedGID); err != nil {
		return err
	}
	if retainReloadDebt {
		wireGuardStateFaultPoint("removal-reload-debt-ready")
		return nil
	}
	return removeTransactionJournal(root, journalRecord, expectedUID, expectedGID)
}

type transactionRecoveryMode uint8

const (
	recoverGeneralTransaction transactionRecoveryMode = iota
	recoverRemovalTransactionOnly
)

func recoverTransaction(
	root string,
	expectedUID, expectedGID uint32,
	mode transactionRecoveryMode,
) (bool, error) {
	operation, present, err := InspectTransaction(root, expectedUID, expectedGID)
	if err != nil {
		return false, err
	}
	if !present {
		return false, nil
	}
	if mode == recoverGeneralTransaction {
		if operation == TransactionOperationRemovePendingReload {
			return false, fmt.Errorf(
				"WireGuard removal is awaiting an external runtime reload and explicit finalization",
			)
		}
	} else if operation != TransactionOperationRemovePendingReload {
		return false, fmt.Errorf(
			"refusing to recover %q as an external-reload WireGuard removal transaction", operation,
		)
	}

	directory, err := openPinnedDirectory(root, filepath.Dir(TransactionPath), expectedUID, expectedGID)
	if err != nil {
		return false, err
	}
	recoveredScratch := false
	if scratchPresent, err := removeReservedTransactionScratchForOperation(
		directory, transactionScratchName, transactionScratchQuarantine,
		expectedUID, expectedGID, operation,
	); err != nil {
		_ = directory.file.Close()
		return false, err
	} else {
		recoveredScratch = recoveredScratch || scratchPresent
	}
	if scratchPresent, err := removeReservedTransactionScratchForOperation(
		directory, transactionNextName, transactionNextQuarantine,
		expectedUID, expectedGID, operation,
	); err != nil {
		_ = directory.file.Close()
		return false, err
	} else {
		recoveredScratch = recoveredScratch || scratchPresent
	}
	if err := directory.file.Close(); err != nil {
		return false, err
	}
	journal, journalRecord, err := readTransactionJournal(root, expectedUID, expectedGID)
	if errors.Is(err, fs.ErrNotExist) {
		return recoveredScratch, nil
	}
	if err != nil {
		return false, fmt.Errorf("read recoverable WireGuard transaction: %w", err)
	}
	if TransactionOperation(journal.Operation) != operation {
		return false, fmt.Errorf(
			"WireGuard transaction operation changed from %q to %q during recovery",
			operation, journal.Operation,
		)
	}
	switch journal.Operation {
	case string(TransactionOperationPublish):
		if mode == recoverRemovalTransactionOnly {
			return false, fmt.Errorf("refusing publication recovery through the removal-only API")
		}
		err = recoverPublishTransaction(root, journal, journalRecord, expectedUID, expectedGID)
	case string(TransactionOperationRemove), string(TransactionOperationRemovePendingReload):
		retainReloadDebt := mode == recoverRemovalTransactionOnly
		err = recoverRemovalTransaction(
			root, journal, journalRecord, expectedUID, expectedGID, retainReloadDebt,
		)
	default:
		err = fmt.Errorf("unsupported WireGuard transaction operation %q", journal.Operation)
	}
	if err != nil {
		return true, err
	}
	return true, nil
}

// Recover completes or rolls back an interrupted bounded publication or
// immediate removal. A removal that carries an external-reload debt is never
// consumed through this general API.
func Recover(root string, expectedUID, expectedGID uint32) (bool, error) {
	return recoverTransaction(root, expectedUID, expectedGID, recoverGeneralTransaction)
}

// RecoverRemoval resumes only a remove-reload journal and retains its durable
// external-reload debt. Publication and immediate-removal journals are never
// mutated through this API.
func RecoverRemoval(root string, expectedUID, expectedGID uint32) (bool, error) {
	return recoverTransaction(root, expectedUID, expectedGID, recoverRemovalTransactionOnly)
}

func beginOwnedArtifactRemoval(
	root string,
	expectedUID, expectedGID uint32,
	operation TransactionOperation,
	retainReloadDebt bool,
) error {
	if !isRemovalOperation(string(operation)) {
		return fmt.Errorf("refusing non-removal WireGuard transaction operation %q", operation)
	}
	manifest, manifestRecord, err := readManifestWithRecord(root, expectedUID, expectedGID)
	if err != nil {
		return err
	}
	if err := VerifyManifest(root, manifest, expectedUID, expectedGID); err != nil {
		return err
	}
	manifestQuarantine, err := randomTemporaryName(filepath.Base(ManifestPath), "quarantine")
	if err != nil {
		return err
	}
	journal := transactionJournal{
		Schema: transactionSchema, Operation: string(operation),
		Artifacts: make([]journalArtifact, 0, len(manifest.Artifacts)),
		Manifest: &journalArtifact{
			Artifact: manifestRecord, QuarantineName: manifestQuarantine,
		},
	}
	if manifest.OpenRCServiceLink != nil {
		quarantineName, err := randomTemporaryName(filepath.Base(OpenRCServiceLinkPath), "quarantine")
		if err != nil {
			return err
		}
		journal.OpenRCServiceLink = &journalSymlink{
			Artifact: *manifest.OpenRCServiceLink, QuarantineName: quarantineName,
		}
	}
	for _, artifact := range manifest.Artifacts {
		quarantineName, err := randomTemporaryName(filepath.Base(artifact.Path), "quarantine")
		if err != nil {
			return err
		}
		journal.Artifacts = append(journal.Artifacts, journalArtifact{
			Artifact: artifact, QuarantineName: quarantineName,
		})
	}
	journalRecord, err := publishTransactionJournal(root, journal, expectedUID, expectedGID)
	if err != nil {
		return fmt.Errorf("begin durable WireGuard removal: %w", err)
	}
	return recoverRemovalTransaction(
		root, journal, journalRecord, expectedUID, expectedGID, retainReloadDebt,
	)
}

func verifyAbsentAt(directory *pinnedDirectory, name, logical string) error {
	var stat unix.Stat_t
	err := unix.Fstatat(int(directory.file.Fd()), name, &stat, unix.AT_SYMLINK_NOFOLLOW)
	if errors.Is(err, unix.ENOENT) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("inspect removal completion path %s: %w", logical, err)
	}
	return fmt.Errorf("WireGuard removal path %s remains", logical)
}

func verifyRemovalJournalComplete(
	root string,
	journal transactionJournal,
	expectedUID, expectedGID uint32,
) error {
	for _, entry := range journal.Artifacts {
		directory, err := openPinnedDirectory(root, filepath.Dir(entry.Artifact.Path), expectedUID, expectedGID)
		if err != nil {
			return err
		}
		finalErr := verifyAbsentAt(directory, filepath.Base(entry.Artifact.Path), entry.Artifact.Path)
		quarantineErr := verifyAbsentAt(
			directory, entry.QuarantineName,
			filepath.Join(filepath.Dir(entry.Artifact.Path), entry.QuarantineName),
		)
		closeErr := directory.file.Close()
		if err := errors.Join(finalErr, quarantineErr, closeErr); err != nil {
			return err
		}
	}
	if journal.Manifest == nil {
		return fmt.Errorf("removal journal is missing its ownership manifest identity")
	}
	manifestDirectory, err := openPinnedDirectory(root, filepath.Dir(ManifestPath), expectedUID, expectedGID)
	if err != nil {
		return err
	}
	manifestFinalErr := verifyAbsentAt(manifestDirectory, filepath.Base(ManifestPath), ManifestPath)
	manifestQuarantineErr := verifyAbsentAt(
		manifestDirectory, journal.Manifest.QuarantineName,
		filepath.Join(filepath.Dir(ManifestPath), journal.Manifest.QuarantineName),
	)
	manifestCloseErr := manifestDirectory.file.Close()
	if err := errors.Join(manifestFinalErr, manifestQuarantineErr, manifestCloseErr); err != nil {
		return err
	}
	if journal.OpenRCServiceLink != nil {
		linkDirectory, err := openPinnedDirectory(
			root, filepath.Dir(OpenRCServiceLinkPath), expectedUID, expectedGID,
		)
		if err != nil {
			return err
		}
		linkFinalErr := verifyAbsentAt(
			linkDirectory, filepath.Base(OpenRCServiceLinkPath), OpenRCServiceLinkPath,
		)
		linkQuarantineErr := verifyAbsentAt(
			linkDirectory, journal.OpenRCServiceLink.QuarantineName,
			filepath.Join(filepath.Dir(OpenRCServiceLinkPath), journal.OpenRCServiceLink.QuarantineName),
		)
		linkCloseErr := linkDirectory.file.Close()
		if err := errors.Join(linkFinalErr, linkQuarantineErr, linkCloseErr); err != nil {
			return err
		}
	}
	transactionDirectory, err := openPinnedDirectory(
		root, filepath.Dir(TransactionPath), expectedUID, expectedGID,
	)
	if err != nil {
		return err
	}
	var scratchErr error
	for _, name := range []string{
		transactionScratchName, transactionScratchQuarantine,
		transactionNextName, transactionNextQuarantine,
	} {
		scratchErr = errors.Join(scratchErr, verifyAbsentAt(
			transactionDirectory, name, filepath.Join(filepath.Dir(TransactionPath), name),
		))
	}
	closeErr := transactionDirectory.file.Close()
	return errors.Join(scratchErr, closeErr)
}

// PrepareRemoval removes only the exact manifest-attributed artifacts and
// retains a durable journal as an external-runtime-reload debt. A retry resumes
// only removal work. The caller must reload the affected runtime state and then
// call FinalizeRemoval.
func PrepareRemoval(root string, expectedUID, expectedGID uint32) (bool, error) {
	operation, transactionPresent, err := InspectTransaction(root, expectedUID, expectedGID)
	if err != nil {
		return false, err
	}
	hadRemovalIntent := false
	if transactionPresent {
		if operation != TransactionOperationRemovePendingReload {
			return false, fmt.Errorf(
				"refusing to prepare external-reload removal while %q transaction recovery is pending", operation,
			)
		}
		recovered, err := RecoverRemoval(root, expectedUID, expectedGID)
		if err != nil {
			return false, err
		}
		hadRemovalIntent = recovered
		operation, transactionPresent, err = InspectTransaction(root, expectedUID, expectedGID)
		if err != nil {
			return false, err
		}
		if transactionPresent {
			if operation != TransactionOperationRemovePendingReload {
				return false, fmt.Errorf("WireGuard removal operation changed during recovery")
			}
			return true, nil
		}
	}
	inventory, err := Inspect(root)
	if err != nil {
		return false, err
	}
	if inventory.Empty() {
		return hadRemovalIntent, nil
	}
	if inventory.Transaction {
		return false, fmt.Errorf("WireGuard transaction appeared while preparing removal")
	}
	if err := beginOwnedArtifactRemoval(
		root, expectedUID, expectedGID,
		TransactionOperationRemovePendingReload, true,
	); err != nil {
		return false, err
	}
	return true, nil
}

// FinalizeRemoval consumes a completed removal debt. It must be called only
// after the caller has successfully reloaded the external runtime state. The
// journal is retained if any generated final, quarantine, or scratch remains.
func FinalizeRemoval(root string, expectedUID, expectedGID uint32) (bool, error) {
	operation, present, err := InspectTransaction(root, expectedUID, expectedGID)
	if err != nil {
		return false, err
	}
	if !present {
		return false, nil
	}
	if operation != TransactionOperationRemovePendingReload {
		return false, fmt.Errorf("refusing to finalize %q as an external-reload WireGuard removal", operation)
	}
	journal, journalRecord, err := readTransactionJournal(root, expectedUID, expectedGID)
	if err != nil {
		return false, fmt.Errorf("read finalizable WireGuard removal debt: %w", err)
	}
	if TransactionOperation(journal.Operation) != operation {
		return false, fmt.Errorf("WireGuard removal operation changed before finalization")
	}
	if err := verifyRemovalJournalComplete(root, journal, expectedUID, expectedGID); err != nil {
		return false, fmt.Errorf("verify completed WireGuard removal before finalization: %w", err)
	}
	if err := removeTransactionJournal(root, journalRecord, expectedUID, expectedGID); err != nil {
		return true, fmt.Errorf("finalize durable WireGuard removal debt: %w", err)
	}
	if _, stillPresent, err := InspectTransaction(root, expectedUID, expectedGID); err != nil {
		return true, err
	} else if stillPresent {
		return true, fmt.Errorf("WireGuard removal debt remains after finalization")
	}
	return true, nil
}

// RemoveOwnedArtifacts removes only the exact verified generated files and the
// exact verified manifest. Parent directories and neighboring files remain.
// Callers that require an external runtime reload must use PrepareRemoval and
// FinalizeRemoval instead so interruption cannot lose the reload debt.
func RemoveOwnedArtifacts(root string, expectedUID, expectedGID uint32) error {
	if _, err := Recover(root, expectedUID, expectedGID); err != nil {
		return fmt.Errorf("recover prior WireGuard transaction before removal: %w", err)
	}
	return beginOwnedArtifactRemoval(
		root, expectedUID, expectedGID, TransactionOperationRemove, false,
	)
}
